async fn continue_assistant_run(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(run_id): Path<String>,
    Json(request): Json<ContinueAssistantRunRequest>,
) -> std::result::Result<(StatusCode, Json<ContinueAssistantRunResponse>), ApiError> {
    let run_id = parse_assistant_run_id(&run_id)?;
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let run = load_visible_assistant_run_for_user(&state, run_id, current_user_id).await?;

    let continue_prompt = request
        .prompt
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("继续执行当前 AssistantRun。")
        .to_string();
    let max_steps = normalize_assistant_run_continue_max_steps(request.max_steps);
    let chat_runtime = resolve_runtime_selection_from_env(
        "ASSISTANT_RUN",
        MODEL_LANE_ASSISTANT_CHAT,
        DEFAULT_ASSISTANT_RUN_RUNTIME_MODEL,
    );
    let react_runtime = resolve_runtime_selection_from_env(
        "ASSISTANT_RUN",
        MODEL_LANE_ASSISTANT_REACT_JSON,
        DEFAULT_ASSISTANT_RUN_RUNTIME_MODEL,
    );
    let mut evidence_state = run.evidence_state.clone();
    let react_enabled = assistant_run_react_enabled(&react_runtime.mode);
    let runtime_mode_for_trail = if react_enabled {
        react_runtime.mode.clone()
    } else {
        chat_runtime.mode.clone()
    };
    let runtime_provider_for_trail = if react_enabled {
        react_runtime.provider.clone()
    } else {
        chat_runtime.provider.clone()
    };
    let runtime_model_for_trail = if react_enabled {
        react_runtime.model.clone()
    } else {
        chat_runtime.model.clone()
    };
    let react_outcome = if react_enabled {
        Some(
            run_assistant_run_react_for_continue(
                &state,
                &run,
                &request,
                &continue_prompt,
                max_steps,
                &mut evidence_state,
                &active_secret_binding_ids,
                current_user_id,
                &react_runtime.mode,
                &react_runtime.provider,
                &react_runtime.model,
            )
            .await?,
        )
    } else {
        None
    };

    let (runtime_manifest, mut react_trail_steps, assistant_artifacts, react_events) =
        match react_outcome {
            Some(outcome) => {
                evidence_state = outcome.evidence_state;
                (
                    outcome.runtime_manifest,
                    outcome.execution_trail_steps,
                    outcome.output_artifacts,
                    outcome.events,
                )
            }
            None => {
                let provider_input = if chat_runtime.mode == "placeholder" {
                    format!(
                        "AssistantRun 继续执行占位回复：后端已接收继续指令，真实模型接入后会基于同一个运行上下文继续回答或请求平台能力。\n\nRun: {}\nContinue prompt: {}\nMax steps: {}\n供料状态: {}",
                        run.id,
                        continue_prompt,
                        max_steps,
                        assistant_run_evidence_status_label(&run.evidence_state)
                    )
                } else {
                    build_assistant_run_continue_provider_input(
                        &run,
                        &request,
                        &continue_prompt,
                        max_steps,
                    )
                };
                let response = complete_assistant_run_provider(
                    MODEL_LANE_ASSISTANT_CHAT,
                    chat_runtime.mode.clone(),
                    chat_runtime.provider.clone(),
                    chat_runtime.model.clone(),
                    provider_input,
                )
                .await
                .map_err(|error| {
                    ApiError::internal("assistant_run_continue_provider_failed", error.to_string())
                })?;
                (
                    render_runtime_manifest(&response.runtime),
                    Vec::new(),
                    vec![json!({
                        "type": "assistant_message",
                        "role": ChatMessageRole::Assistant.as_str(),
                        "content": response.output_text,
                        "source": "assistant_run_continue",
                    })],
                    Vec::new(),
                )
            }
        };

    let now = Utc::now();
    let mut execution_trail = value_array(run.execution_trail.clone());
    execution_trail.push(json!({
        "status": "completed",
        "label": "继续执行",
        "prompt": continue_prompt,
        "max_steps": max_steps,
        "react_enabled": react_enabled,
        "runtime_mode": runtime_mode_for_trail,
        "provider": runtime_provider_for_trail,
        "model": runtime_model_for_trail,
        "at": now,
    }));
    execution_trail.append(&mut react_trail_steps);
    let mut output_artifacts = value_array(run.output_artifacts.clone());
    output_artifacts.extend(assistant_artifacts.into_iter().map(|mut artifact| {
        if let Some(object) = artifact.as_object_mut() {
            object
                .entry("created_at".to_string())
                .or_insert_with(|| json!(now));
        }
        artifact
    }));

    state
        .storage
        .assistant_runs()
        .update_execution_trail(
            state.tenant_id,
            run_id,
            &Value::Array(execution_trail.clone()),
        )
        .await
        .map_err(ApiError::from_storage)?;
    state
        .storage
        .assistant_runs()
        .update_evidence_state(state.tenant_id, run_id, &evidence_state)
        .await
        .map_err(ApiError::from_storage)?;
    let updated_run = state
        .storage
        .assistant_runs()
        .attach_output_artifacts(
            state.tenant_id,
            run_id,
            &Value::Array(output_artifacts.clone()),
        )
        .await
        .map_err(ApiError::from_storage)?;
    for event in react_events {
        state
            .storage
            .assistant_runs()
            .append_event(
                state.tenant_id,
                run_id,
                &NewAssistantRunEvent {
                    event_name: event.event_name,
                    payload: event.payload,
                    created_at: now,
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
    }
    let event = state
        .storage
        .assistant_runs()
        .append_event(
            state.tenant_id,
            run_id,
            &NewAssistantRunEvent {
                event_name: "assistant_run.continued".to_string(),
                payload: json!({
                    "prompt": continue_prompt,
                    "max_steps": max_steps,
                    "runtime": runtime_manifest.clone(),
                }),
                created_at: now,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;
    let assistant_message = AssistantRunMessageView {
        role: ChatMessageRole::Assistant,
        content: output_artifacts
            .last()
            .and_then(|artifact| artifact.get("content"))
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
    };
    let selected_scope = updated_run.selected_scope.clone();
    let evidence_state = updated_run.evidence_state.clone();
    let run_view = to_assistant_run_view(updated_run);

    Ok((
        StatusCode::CREATED,
        Json(ContinueAssistantRunResponse {
            run: run_view,
            assistant_message,
            runtime: runtime_manifest,
            event: to_assistant_run_event_view(event),
            selected_scope,
            evidence_state,
            execution_trail,
            output_artifacts,
            required_confirmations: Vec::new(),
        }),
    ))
}

