async fn list_conversation_memory_items(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<ConversationMemoryQuery>,
) -> std::result::Result<Json<Vec<ConversationMemoryItemView>>, ApiError> {
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let local_thread_id = required_field("local_thread_id", query.local_thread_id)?;
    validate_required("local_thread_id", &local_thread_id)?;
    let items = state
        .storage
        .conversation_memory_items()
        .list_by_local_thread(
            state.tenant_id,
            local_thread_id.trim(),
            query.query.as_deref(),
            query.limit.unwrap_or(20),
        )
        .await
        .map_err(ApiError::from_storage)?;

    Ok(Json(
        items
            .into_iter()
            .filter(|item| owner_user_id_is_visible(item.user_id, current_user_id))
            .map(to_conversation_memory_item_view)
            .collect(),
    ))
}

async fn list_assistant_run_conversation_memory_candidates(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(run_id): Path<String>,
    Query(query): Query<ConversationMemoryQuery>,
) -> std::result::Result<Json<Vec<ConversationMemoryItemView>>, ApiError> {
    let run_id = parse_assistant_run_id(&run_id)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let run = load_visible_assistant_run_for_user(&state, run_id, current_user_id).await?;
    let local_thread_id = run.local_thread_id.ok_or_else(|| {
        ApiError::bad_request(
            "assistant_run_local_thread_missing",
            "assistant run has no local thread id for conversation memory lookup".to_string(),
        )
    })?;
    let items = state
        .storage
        .conversation_memory_items()
        .list_by_local_thread(
            state.tenant_id,
            local_thread_id.trim(),
            query.query.as_deref(),
            query.limit.unwrap_or(20),
        )
        .await
        .map_err(ApiError::from_storage)?;

    Ok(Json(
        items
            .into_iter()
            .filter(|item| owner_user_id_is_visible(item.user_id, current_user_id))
            .map(to_conversation_memory_item_view)
            .collect(),
    ))
}

#[cfg(test)]
fn build_assistant_run_provider_input(request: &CreateAssistantRunRequest) -> String {
    build_assistant_run_provider_input_with_evidence(request, None)
}

fn build_assistant_run_provider_input_with_evidence(
    request: &CreateAssistantRunRequest,
    evidence_state: Option<&Value>,
) -> String {
    let mut sections = vec![
        "你是智能数据工作台里的普通聊天运行时。".to_string(),
        "原则：不替用户编排答案；只根据用户问题、启动简报、范围候选和必要历史直接回答。"
            .to_string(),
        "系统能力：可普通聊天、检索供料、读取文档细节、读取音视频转写/场景等媒体细节、创建报表、规划/渲染/修改静态页、导出静态页 ZIP 交付包；缺数据时必须说明缺失，不能编造指标。"
            .to_string(),
    ];

    if let Some(briefing) = request.startup_briefing.as_ref() {
        sections.push(format!(
            "启动简报：{}",
            serde_json::to_string(briefing).unwrap_or_else(|_| "{}".to_string())
        ));
    }
    if !request.scope_candidates.is_empty() {
        sections.push(format!(
            "范围候选：{}",
            serde_json::to_string(&request.scope_candidates).unwrap_or_else(|_| "[]".to_string())
        ));
    }
    if let Some(selected_scope) = request.selected_scope.as_ref() {
        sections.push(format!(
            "当前选中范围：{}",
            serde_json::to_string(selected_scope).unwrap_or_else(|_| "{}".to_string())
        ));
    }
    if let Some(evidence_state) = evidence_state {
        if evidence_state.get("status").and_then(Value::as_str) != Some("not_requested") {
            sections.push(format!(
                "供料证据：{}",
                serde_json::to_string(evidence_state).unwrap_or_else(|_| "{}".to_string())
            ));
        }
    }
    if let Some(current_artifact) = request.current_artifact.as_ref() {
        sections.push(format!(
            "当前打开产物：{}",
            serde_json::to_string(current_artifact).unwrap_or_else(|_| "{}".to_string())
        ));
    }

    let history = request
        .messages
        .iter()
        .rev()
        .take(12)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .map(|message| format!("{}: {}", message.role.as_str(), message.content.trim()))
        .collect::<Vec<_>>();
    if !history.is_empty() {
        sections.push(format!("最近对话：\n{}", history.join("\n")));
    }

    sections.push(format!("用户问题：{}", request.prompt.trim()));
    sections.join("\n\n")
}

fn build_assistant_run_continue_provider_input(
    run: &AssistantRun,
    request: &ContinueAssistantRunRequest,
    continue_prompt: &str,
    max_steps: usize,
) -> String {
    let mut sections = vec![
        "你是智能数据工作台里的 AssistantRun 连续执行运行时。".to_string(),
        "原则：不替用户编造系统动作；如果需要平台能力，只提出下一步动作需求；基于已有供料直接继续回答。"
            .to_string(),
        format!("运行ID：{}", run.id),
        format!("原始问题：{}", run.user_prompt.trim()),
        format!("继续指令：{}", continue_prompt.trim()),
        format!("本次最多连续动作数：{}", max_steps),
        format!(
            "当前选中范围：{}",
            serde_json::to_string(&run.selected_scope).unwrap_or_else(|_| "{}".to_string())
        ),
        format!(
            "供料状态：{}",
            serde_json::to_string(&run.evidence_state).unwrap_or_else(|_| "{}".to_string())
        ),
    ];

    if let Some(current_artifact) = request.current_artifact.as_ref() {
        sections.push(format!(
            "当前打开产物：{}",
            serde_json::to_string(current_artifact).unwrap_or_else(|_| "{}".to_string())
        ));
    }

    let history = request
        .messages
        .iter()
        .rev()
        .take(8)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .map(|message| format!("{}: {}", message.role.as_str(), message.content.trim()))
        .collect::<Vec<_>>();
    if !history.is_empty() {
        sections.push(format!("继续前最近对话：\n{}", history.join("\n")));
    }

    sections.join("\n\n")
}

fn build_assistant_run_context_policy(selected_scope: &Value) -> Value {
    let supply_policy = selected_scope
        .get("supply_policy")
        .or_else(|| selected_scope.get("supplyPolicy"))
        .cloned()
        .unwrap_or_else(|| {
            json!({
                "intent": assistant_run_scope_intent(selected_scope),
                "retrievalPolicy": if selected_dataset_ids_from_scope(selected_scope).is_empty() {
                    "not_requested"
                } else {
                    "standard"
                },
                "preferDetail": false,
                "noFakeData": true,
            })
        });
    let retrieval_policy = supply_policy
        .get("retrievalPolicy")
        .or_else(|| supply_policy.get("retrieval_policy"))
        .cloned()
        .unwrap_or_else(|| json!("standard"));
    json!({
        "history_policy": if selected_scope_requests_conversation_memory(selected_scope) {
            "intent_gated_selected"
        } else {
            "intent_gated"
        },
        "supply_policy": "host_supplies_model_answers",
        "retrieval_policy": retrieval_policy,
        "action_policy": assistant_run_scope_action_policy(selected_scope),
        "context_budget_policy": assistant_run_scope_context_budget_policy(selected_scope),
        "candidate_policy": assistant_run_scope_candidate_policy(selected_scope),
        "recommended_tool_actions": assistant_run_scope_recommended_tool_actions(selected_scope),
        "assistant_intent": assistant_run_scope_intent(selected_scope),
        "scope_supply_policy": supply_policy,
    })
}

async fn complete_assistant_run_provider(
    model_lane: &'static str,
    runtime_mode: String,
    runtime_provider: String,
    runtime_model: String,
    provider_input: String,
) -> std::result::Result<LlmResponse, ApiError> {
    tokio::task::spawn_blocking(move || {
        let provider = build_provider_from_env(
            "ASSISTANT_RUN",
            &runtime_mode,
            runtime_provider,
            bootstrap_default_prompt_registry(),
        )?;
        provider.complete(&LlmRequest {
            model: runtime_model,
            lane: Some(model_lane.to_string()),
            system_prompt_key: None,
            input: provider_input,
        })
    })
    .await
    .map_err(|error| {
        ApiError::internal(
            "assistant_run_join_failed",
            format!("assistant run worker join failed: {error}"),
        )
    })?
    .map_err(|error| ApiError::internal("assistant_run_provider_failed", error.to_string()))
}

async fn run_assistant_run_react_for_create(
    state: &AppState,
    request: &CreateAssistantRunRequest,
    selected_scope: &Value,
    initial_evidence_state: Value,
    local_thread_id: Option<&str>,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    runtime_mode: &str,
    runtime_provider: &str,
    runtime_model: &str,
) -> std::result::Result<AssistantRunReactOutcome, ApiError> {
    let max_steps = assistant_run_react_max_steps();
    let mut evidence_state = initial_evidence_state;
    let mut observations = Vec::<Value>::new();
    let mut events = Vec::<AssistantRunReactEvent>::new();
    let mut execution_trail_steps = Vec::<Value>::new();
    let trace_id = Uuid::new_v4();
    let mut react_trace_steps = Vec::<Value>::new();
    let mut runtime_manifest = json!({
        "mode": runtime_mode,
        "provider": runtime_provider,
        "model": runtime_model,
        "react": {
            "enabled": true,
            "max_steps": max_steps,
        },
    });
    let mut assistant_message = String::new();

    for step_index in 1..=max_steps {
        let step_started = Instant::now();
        let provider_input = build_assistant_run_react_provider_input(
            request,
            Some(&evidence_state),
            &observations,
            step_index,
            max_steps,
        );
        let response = complete_assistant_run_provider(
            MODEL_LANE_ASSISTANT_REACT_JSON,
            runtime_mode.to_string(),
            runtime_provider.to_string(),
            runtime_model.to_string(),
            provider_input,
        )
        .await?;
        runtime_manifest = render_runtime_manifest(&response.runtime);

        let action = match parse_assistant_run_next_action(&response.output_text) {
            Ok(action) => action,
            Err(error) => {
                assistant_message = response.output_text.trim().to_string();
                if assistant_message.is_empty() {
                    assistant_message = format!("模型未返回有效 ReAct 动作：{error}");
                }
                events.push(AssistantRunReactEvent {
                    event_name: "assistant_run.react.invalid_action".to_string(),
                    payload: json!({
                        "step": step_index,
                        "safe_error_code": "invalid_action",
                        "fallback": "final_answer",
                    }),
                });
                react_trace_steps.push(assistant_run_react_invalid_trace_step(
                    trace_id,
                    None,
                    step_index,
                    "invalid_action",
                    step_started.elapsed().as_millis(),
                ));
                execution_trail_steps.push(json!({
                    "status": "completed",
                    "label": "模型直接回答",
                    "react_step": step_index,
                    "fallback": "invalid_action",
                    "at": Utc::now(),
                }));
                break;
            }
        };

        events.push(AssistantRunReactEvent {
            event_name: "assistant_run.react.action_requested".to_string(),
            payload: json!({
                "step": step_index,
                "action_type": action.action_type.as_str(),
                "reason_summary": redact_react_trace_text(&action.reason_summary, ASSISTANT_RUN_REACT_REASON_TRACE_LIMIT),
                "requires_confirmation": action.requires_confirmation,
            }),
        });

        let result = if let Some(repair) = build_react_protocol_repair_at_step(
            &action,
            &observations,
            selected_scope,
            &evidence_state,
            step_index,
        ) {
            Ok(repair)
        } else {
            execute_assistant_run_react_action(
                state,
                &action,
                selected_scope,
                &mut evidence_state,
                request.current_artifact.as_ref(),
                None,
                request.prompt.trim(),
                local_thread_id,
                active_secret_binding_ids,
                current_user_id,
            )
            .await
        };

        let result = match result {
            Ok(result) => result,
            Err(_) => AssistantRunReactActionResult {
                observation: json!({
                    "status": "failed",
                    "action_type": action.action_type.as_str(),
                    "error_code": "tool_failed",
                }),
                trail_step: json!({
                    "status": "failed",
                    "label": assistant_run_react_action_label(&action.action_type),
                    "react_step": step_index,
                    "error_code": "tool_failed",
                    "at": Utc::now(),
                }),
                final_answer: None,
            },
        };

        let observation_summary = assistant_run_react_observation_summary(&result.observation);
        react_trace_steps.push(assistant_run_react_trace_step(
            trace_id,
            None,
            step_index,
            &action,
            &observation_summary,
            step_started.elapsed().as_millis(),
        ));
        observations.push(result.observation.clone());
        execution_trail_steps.push(result.trail_step);
        events.push(AssistantRunReactEvent {
            event_name: if result.final_answer.is_some() {
                "assistant_run.react.final_answer".to_string()
            } else {
                "assistant_run.react.action_completed".to_string()
            },
            payload: json!({
                "step": step_index,
                "action_type": action.action_type.as_str(),
                "observation_summary": observation_summary,
            }),
        });

        if let Some(final_answer) = result.final_answer {
            assistant_message = final_answer;
            break;
        }
    }

    if assistant_message.trim().is_empty() {
        assistant_message = format!(
            "已达到连续执行步数上限（{} 步）。请确认是否继续，或补充下一步要求。",
            max_steps
        );
        events.push(AssistantRunReactEvent {
            event_name: "assistant_run.react.step_limit_reached".to_string(),
            payload: json!({
                "max_steps": max_steps,
                "observation_count": observations.len(),
            }),
        });
        execution_trail_steps.push(json!({
            "status": "completed",
            "label": "达到连续执行上限",
            "max_steps": max_steps,
            "at": Utc::now(),
        }));
    }
    assistant_run_react_attach_trace(&mut runtime_manifest, trace_id, None, &react_trace_steps);
    execution_trail_steps.push(assistant_run_react_trace_trail_step(
        trace_id,
        None,
        &react_trace_steps,
    ));

    let output_artifacts = vec![json!({
        "type": "assistant_message",
        "role": ChatMessageRole::Assistant.as_str(),
        "content": assistant_message,
        "source": "assistant_run_react",
    })];

    Ok(AssistantRunReactOutcome {
        runtime_manifest,
        evidence_state,
        execution_trail_steps,
        output_artifacts,
        events,
    })
}

async fn run_assistant_run_react_for_continue(
    state: &AppState,
    run: &AssistantRun,
    request: &ContinueAssistantRunRequest,
    continue_prompt: &str,
    max_steps: usize,
    initial_evidence_state: &mut Value,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    runtime_mode: &str,
    runtime_provider: &str,
    runtime_model: &str,
) -> std::result::Result<AssistantRunReactOutcome, ApiError> {
    let max_steps = max_steps.clamp(1, ASSISTANT_RUN_REACT_MAX_STEPS);
    let mut evidence_state = initial_evidence_state.clone();
    let mut observations = Vec::<Value>::new();
    let mut events = Vec::<AssistantRunReactEvent>::new();
    let mut execution_trail_steps = Vec::<Value>::new();
    let trace_id = Uuid::new_v4();
    let mut react_trace_steps = Vec::<Value>::new();
    let mut runtime_manifest = json!({
        "mode": runtime_mode,
        "provider": runtime_provider,
        "model": runtime_model,
        "react": {
            "enabled": true,
            "max_steps": max_steps,
            "entrypoint": "continue_assistant_run",
        },
    });
    let mut assistant_message = String::new();

    for step_index in 1..=max_steps {
        let step_started = Instant::now();
        let provider_input = build_assistant_run_react_continue_provider_input(
            run,
            request,
            continue_prompt,
            Some(&evidence_state),
            &observations,
            step_index,
            max_steps,
        );
        let response = complete_assistant_run_provider(
            MODEL_LANE_ASSISTANT_REACT_JSON,
            runtime_mode.to_string(),
            runtime_provider.to_string(),
            runtime_model.to_string(),
            provider_input,
        )
        .await?;
        runtime_manifest = render_runtime_manifest(&response.runtime);

        let action = match parse_assistant_run_next_action(&response.output_text) {
            Ok(action) => action,
            Err(error) => {
                assistant_message = response.output_text.trim().to_string();
                if assistant_message.is_empty() {
                    assistant_message = format!("模型未返回有效 ReAct 动作：{error}");
                }
                events.push(AssistantRunReactEvent {
                    event_name: "assistant_run.react.invalid_action".to_string(),
                    payload: json!({
                        "step": step_index,
                        "safe_error_code": "invalid_action",
                        "fallback": "final_answer",
                        "entrypoint": "continue_assistant_run",
                    }),
                });
                react_trace_steps.push(assistant_run_react_invalid_trace_step(
                    trace_id,
                    Some(run.id),
                    step_index,
                    "invalid_action",
                    step_started.elapsed().as_millis(),
                ));
                execution_trail_steps.push(json!({
                    "status": "completed",
                    "label": "模型直接回答",
                    "react_step": step_index,
                    "fallback": "invalid_action",
                    "at": Utc::now(),
                }));
                break;
            }
        };

        events.push(AssistantRunReactEvent {
            event_name: "assistant_run.react.action_requested".to_string(),
            payload: json!({
                "step": step_index,
                "action_type": action.action_type.as_str(),
                "reason_summary": redact_react_trace_text(&action.reason_summary, ASSISTANT_RUN_REACT_REASON_TRACE_LIMIT),
                "requires_confirmation": action.requires_confirmation,
                "entrypoint": "continue_assistant_run",
            }),
        });

        let result = if let Some(repair) = build_react_protocol_repair_at_step(
            &action,
            &observations,
            &run.selected_scope,
            &evidence_state,
            step_index,
        ) {
            Ok(repair)
        } else {
            execute_assistant_run_react_action(
                state,
                &action,
                &run.selected_scope,
                &mut evidence_state,
                request.current_artifact.as_ref(),
                Some(run.id),
                continue_prompt.trim(),
                run.local_thread_id.as_deref(),
                active_secret_binding_ids,
                current_user_id,
            )
            .await
        };

        let result = match result {
            Ok(result) => result,
            Err(_) => AssistantRunReactActionResult {
                observation: json!({
                    "status": "failed",
                    "action_type": action.action_type.as_str(),
                    "error_code": "tool_failed",
                }),
                trail_step: json!({
                    "status": "failed",
                    "label": assistant_run_react_action_label(&action.action_type),
                    "react_step": step_index,
                    "error_code": "tool_failed",
                    "at": Utc::now(),
                }),
                final_answer: None,
            },
        };

        let observation_summary = assistant_run_react_observation_summary(&result.observation);
        react_trace_steps.push(assistant_run_react_trace_step(
            trace_id,
            Some(run.id),
            step_index,
            &action,
            &observation_summary,
            step_started.elapsed().as_millis(),
        ));
        observations.push(result.observation.clone());
        execution_trail_steps.push(result.trail_step);
        events.push(AssistantRunReactEvent {
            event_name: if result.final_answer.is_some() {
                "assistant_run.react.final_answer".to_string()
            } else {
                "assistant_run.react.action_completed".to_string()
            },
            payload: json!({
                "step": step_index,
                "action_type": action.action_type.as_str(),
                "observation_summary": observation_summary,
                "entrypoint": "continue_assistant_run",
            }),
        });

        if let Some(final_answer) = result.final_answer {
            assistant_message = final_answer;
            break;
        }
    }

    if assistant_message.trim().is_empty() {
        assistant_message = format!(
            "已达到连续执行步数上限（{} 步）。请确认是否继续，或补充下一步要求。",
            max_steps
        );
        events.push(AssistantRunReactEvent {
            event_name: "assistant_run.react.step_limit_reached".to_string(),
            payload: json!({
                "max_steps": max_steps,
                "observation_count": observations.len(),
                "entrypoint": "continue_assistant_run",
            }),
        });
        execution_trail_steps.push(json!({
            "status": "completed",
            "label": "达到连续执行上限",
            "max_steps": max_steps,
            "at": Utc::now(),
        }));
    }

    assistant_run_react_attach_trace(
        &mut runtime_manifest,
        trace_id,
        Some(run.id),
        &react_trace_steps,
    );
    execution_trail_steps.push(assistant_run_react_trace_trail_step(
        trace_id,
        Some(run.id),
        &react_trace_steps,
    ));

    *initial_evidence_state = evidence_state.clone();
    let output_artifacts = vec![json!({
        "type": "assistant_message",
        "role": ChatMessageRole::Assistant.as_str(),
        "content": assistant_message,
        "source": "assistant_run_react_continue",
    })];

    Ok(AssistantRunReactOutcome {
        runtime_manifest,
        evidence_state,
        execution_trail_steps,
        output_artifacts,
        events,
    })
}

fn build_assistant_run_react_provider_input(
    request: &CreateAssistantRunRequest,
    evidence_state: Option<&Value>,
    observations: &[Value],
    step_index: usize,
    max_steps: usize,
) -> String {
    let null_value = Value::Null;
    let startup_briefing = request.startup_briefing.as_ref().unwrap_or(&null_value);
    let selected_scope = request.selected_scope.as_ref().unwrap_or(&null_value);
    let evidence_for_catalog = evidence_state.unwrap_or(&null_value);
    let planning_catalog = build_assistant_run_react_planning_catalog(
        startup_briefing,
        &request.scope_candidates,
        selected_scope,
        evidence_for_catalog,
    );
    let mut sections = vec![
        "你是智能数据工作台里的 Host-Controlled ReAct 运行时。".to_string(),
        "你只能提出下一步动作，不能假装已经执行平台动作。V3 Host 会验证、执行、记录并返回 observation。".to_string(),
        "只返回一个 JSON 对象，禁止 Markdown，禁止解释 JSON 外的文字。".to_string(),
        "JSON Schema: {\"action_type\":\"retrieve_evidence|read_document_detail|recall_conversation_memory|list_report_options|report_choice|create_static_page_draft|update_static_page_module|submit_static_page_image_preview|render_static_page|create_report_draft|openclaw_memory_recall|openclaw_readonly_execution|codex_host_task|final_answer\",\"reason_summary\":\"给用户看的简短原因\",\"arguments\":{},\"requires_confirmation\":false}".to_string(),
        "目录、候选列表和系统说明只用于规划下一步，不是可引用证据。".to_string(),
        "选中数据集或对话记忆时，final_answer 必须基于已返回的 observation；否则先选择 retrieve_evidence、read_document_detail 或 recall_conversation_memory。".to_string(),
        "工具选择：retrieve_evidence 用于发现候选证据；read_document_detail 用于需要原文措辞、OCR、表格、音视频转写/场景或画像字段等细节时，document_id 必须来自选中范围或已返回 observation；最终引用只能来自 observation。".to_string(),
        "如果弱规划目录或供料证据里出现 detailTargets，优先用其中的 document_id 调 read_document_detail；detailTargets 只是深读目标，不是可引用证据。".to_string(),
        "静态页或报表意图且存在数据集时，优先 retrieve_evidence；若需要模块数据、字段、表格/OCR 或原文措辞，继续 read_document_detail，再创建静态页/报表动作。".to_string(),
        "如果当前打开产物是静态页草稿，用户要求修改标题、内容、图表、数据绑定或布局时，优先用 update_static_page_module；Host 只会把操作应用到当前已持久化草稿。".to_string(),
        "OpenClaw 和 Codex Host 都是可选外挂能力；openclaw_memory_recall、openclaw_readonly_execution、codex_host_task 可能被 Host 拒绝，不能绕过 V3 选中范围、记忆、任务隔离和执行 allowlist。".to_string(),
        "如果用户表达报表意图，先用 list_report_options；收到该 observation 后，才能用 report_choice，并只在 arguments.choice 填 continue_qa 或 create_report，不能编写报表正文。".to_string(),
        "如果已经可以回答，使用 action_type=final_answer，arguments.content 放最终正文。".to_string(),
        format!("当前 ReAct 步骤：{step_index}/{max_steps}"),
    ];
    sections.push(format!(
        "弱规划目录（只用于选择工具，不可直接作为回答证据）：{}",
        serde_json::to_string(&planning_catalog).unwrap_or_else(|_| "{}".to_string())
    ));
    if let Some(evidence_state) = evidence_state {
        if evidence_state.get("status").and_then(Value::as_str) != Some("not_requested") {
            sections.push(format!(
                "可回答供料证据：{}",
                serde_json::to_string(evidence_state).unwrap_or_else(|_| "{}".to_string())
            ));
        }
    }
    if let Some(current_artifact) = request.current_artifact.as_ref() {
        sections.push(format!(
            "当前打开产物：{}",
            serde_json::to_string(current_artifact).unwrap_or_else(|_| "{}".to_string())
        ));
    }
    let history = request
        .messages
        .iter()
        .rev()
        .take(8)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .map(|message| format!("{}: {}", message.role.as_str(), message.content.trim()))
        .collect::<Vec<_>>();
    if !history.is_empty() {
        sections.push(format!("最近对话：\n{}", history.join("\n")));
    }
    if !observations.is_empty() {
        sections.push(format!(
            "已完成 observation：{}",
            serde_json::to_string(observations).unwrap_or_else(|_| "[]".to_string())
        ));
    }
    sections.push(format!("用户问题：{}", request.prompt.trim()));
    sections.join("\n\n")
}

fn build_assistant_run_react_continue_provider_input(
    run: &AssistantRun,
    request: &ContinueAssistantRunRequest,
    continue_prompt: &str,
    evidence_state: Option<&Value>,
    observations: &[Value],
    step_index: usize,
    max_steps: usize,
) -> String {
    let null_value = Value::Null;
    let scope_candidates = value_array(run.scope_candidates.clone());
    let evidence_for_catalog = evidence_state.unwrap_or(&null_value);
    let planning_catalog = build_assistant_run_react_planning_catalog(
        &run.startup_briefing,
        &scope_candidates,
        &run.selected_scope,
        evidence_for_catalog,
    );
    let mut sections = vec![
        "你是智能数据工作台里的 Host-Controlled ReAct 继续执行运行时。".to_string(),
        "你只能提出下一步动作，不能假装已经执行平台动作。V3 Host 会验证、执行、记录并返回 observation。".to_string(),
        "只返回一个 JSON 对象，禁止 Markdown，禁止解释 JSON 外的文字。".to_string(),
        "JSON Schema: {\"action_type\":\"retrieve_evidence|read_document_detail|recall_conversation_memory|list_report_options|report_choice|create_static_page_draft|update_static_page_module|submit_static_page_image_preview|render_static_page|create_report_draft|openclaw_memory_recall|openclaw_readonly_execution|codex_host_task|final_answer\",\"reason_summary\":\"给用户看的简短原因\",\"arguments\":{},\"requires_confirmation\":false}".to_string(),
        "目录、候选列表和系统说明只用于规划下一步，不是可引用证据。".to_string(),
        "选中数据集或对话记忆时，final_answer 必须基于已返回的 observation；否则先选择 retrieve_evidence、read_document_detail 或 recall_conversation_memory。".to_string(),
        "工具选择：retrieve_evidence 用于发现候选证据；read_document_detail 用于需要原文措辞、OCR、表格、音视频转写/场景或画像字段等细节时，document_id 必须来自选中范围或已返回 observation；最终引用只能来自 observation。".to_string(),
        "如果弱规划目录或供料证据里出现 detailTargets，优先用其中的 document_id 调 read_document_detail；detailTargets 只是深读目标，不是可引用证据。".to_string(),
        "静态页或报表意图且存在数据集时，优先 retrieve_evidence；若需要模块数据、字段、表格/OCR 或原文措辞，继续 read_document_detail，再创建静态页/报表动作。".to_string(),
        "如果当前打开产物是静态页草稿，用户要求修改标题、内容、图表、数据绑定或布局时，优先用 update_static_page_module；Host 只会把操作应用到当前已持久化草稿。".to_string(),
        "OpenClaw 和 Codex Host 都是可选外挂能力；openclaw_memory_recall、openclaw_readonly_execution、codex_host_task 可能被 Host 拒绝，不能绕过 V3 选中范围、记忆、任务隔离和执行 allowlist。".to_string(),
        "如果用户表达报表意图，先用 list_report_options；收到该 observation 后，才能用 report_choice，并只在 arguments.choice 填 continue_qa 或 create_report，不能编写报表正文。".to_string(),
        "如果已经可以回答，使用 action_type=final_answer，arguments.content 放最终正文。".to_string(),
        format!("当前 ReAct 步骤：{step_index}/{max_steps}"),
        format!("运行ID：{}", run.id),
        format!("原始问题：{}", run.user_prompt.trim()),
        format!("继续指令：{}", continue_prompt.trim()),
        format!(
            "弱规划目录（只用于选择工具，不可直接作为回答证据）：{}",
            serde_json::to_string(&planning_catalog).unwrap_or_else(|_| "{}".to_string())
        ),
    ];
    if let Some(evidence_state) = evidence_state {
        if evidence_state.get("status").and_then(Value::as_str) != Some("not_requested") {
            sections.push(format!(
                "可回答供料证据：{}",
                serde_json::to_string(evidence_state).unwrap_or_else(|_| "{}".to_string())
            ));
        }
    }

    if let Some(current_artifact) = request.current_artifact.as_ref() {
        sections.push(format!(
            "当前打开产物：{}",
            serde_json::to_string(current_artifact).unwrap_or_else(|_| "{}".to_string())
        ));
    }

    let history = request
        .messages
        .iter()
        .rev()
        .take(8)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .map(|message| format!("{}: {}", message.role.as_str(), message.content.trim()))
        .collect::<Vec<_>>();
    if !history.is_empty() {
        sections.push(format!("继续前最近对话：\n{}", history.join("\n")));
    }
    if !observations.is_empty() {
        sections.push(format!(
            "已完成 observation：{}",
            serde_json::to_string(observations).unwrap_or_else(|_| "[]".to_string())
        ));
    }

    sections.join("\n\n")
}

fn assistant_run_react_enabled(runtime_mode: &str) -> bool {
    runtime_mode != "placeholder" && env_flag("ASSISTANT_RUN_REACT_ENABLED", false)
}

fn assistant_run_react_max_steps() -> usize {
    std::env::var("ASSISTANT_RUN_REACT_MAX_STEPS")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(ASSISTANT_RUN_REACT_DEFAULT_MAX_STEPS)
        .clamp(1, ASSISTANT_RUN_REACT_MAX_STEPS)
}

fn assistant_run_react_attach_trace(
    runtime_manifest: &mut Value,
    trace_id: Uuid,
    assistant_run_id: Option<AssistantRunId>,
    trace_steps: &[Value],
) {
    let trace = assistant_run_react_trace_manifest(trace_id, assistant_run_id, trace_steps);
    if let Some(object) = runtime_manifest.as_object_mut() {
        object.insert("react_trace".to_string(), trace);
    } else {
        *runtime_manifest = json!({
            "runtime": runtime_manifest.clone(),
            "react_trace": trace,
        });
    }
}

fn assistant_run_react_trace_manifest(
    trace_id: Uuid,
    assistant_run_id: Option<AssistantRunId>,
    trace_steps: &[Value],
) -> Value {
    json!({
        "trace_id": trace_id.to_string(),
        "assistant_run_id": assistant_run_id.map(|id| id.to_string()),
        "steps": trace_steps,
    })
}

fn assistant_run_react_trace_trail_step(
    trace_id: Uuid,
    assistant_run_id: Option<AssistantRunId>,
    trace_steps: &[Value],
) -> Value {
    json!({
        "status": "completed",
        "label": "ReAct 安全追踪",
        "trace_id": trace_id.to_string(),
        "assistant_run_id": assistant_run_id.map(|id| id.to_string()),
        "step_count": trace_steps.len(),
        "react_trace": trace_steps,
        "at": Utc::now(),
    })
}

fn assistant_run_react_invalid_trace_step(
    trace_id: Uuid,
    assistant_run_id: Option<AssistantRunId>,
    pass_number: usize,
    safe_error_code: &str,
    duration_ms: u128,
) -> Value {
    json!({
        "trace_id": trace_id.to_string(),
        "assistant_run_id": assistant_run_id.map(|id| id.to_string()),
        "pass_number": pass_number,
        "action_type": "invalid_action",
        "reason_summary": "",
        "status": "failed",
        "denied_count": 0,
        "returned_count": 0,
        "duration_ms": bounded_duration_ms(duration_ms),
        "safe_error_code": safe_error_code,
        "safe_message": "模型未返回有效动作",
    })
}

fn assistant_run_react_trace_step(
    trace_id: Uuid,
    assistant_run_id: Option<AssistantRunId>,
    pass_number: usize,
    action: &AssistantRunNextAction,
    observation_summary: &Value,
    duration_ms: u128,
) -> Value {
    json!({
        "trace_id": trace_id.to_string(),
        "assistant_run_id": assistant_run_id.map(|id| id.to_string()),
        "pass_number": pass_number,
        "action_type": action.action_type.as_str(),
        "reason_summary": redact_react_trace_text(&action.reason_summary, ASSISTANT_RUN_REACT_REASON_TRACE_LIMIT),
        "status": observation_summary.get("status").and_then(Value::as_str).unwrap_or("unknown"),
        "denied_count": observation_summary.get("denied_count").and_then(Value::as_u64).unwrap_or(0),
        "returned_count": observation_summary.get("returned_count").and_then(Value::as_u64).unwrap_or(0),
        "detail_target_count": observation_summary.get("detail_target_count").and_then(Value::as_u64).unwrap_or(0),
        "duration_ms": bounded_duration_ms(duration_ms),
        "safe_error_code": observation_summary.get("safe_error_code").cloned().unwrap_or(Value::Null),
        "safe_message": observation_summary.get("safe_message").and_then(Value::as_str).unwrap_or(""),
    })
}

fn assistant_run_react_observation_summary(observation: &Value) -> Value {
    let status = observation
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let action_type = observation
        .get("action_type")
        .or_else(|| observation.get("actionType"))
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let denied_count = observation
        .get("denied")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or_default();
    let returned_count = assistant_run_react_returned_count(observation);
    let detail_target_count = observation
        .get("detail_target_count")
        .or_else(|| observation.get("detailTargetCount"))
        .and_then(Value::as_u64)
        .unwrap_or_default();
    let safe_error_code = observation
        .get("repair_code")
        .or_else(|| observation.get("error_code"))
        .and_then(Value::as_str)
        .map(|value| redact_react_trace_text(value, ASSISTANT_RUN_REACT_MESSAGE_TRACE_LIMIT))
        .or_else(|| {
            observation
                .get("error")
                .and_then(Value::as_str)
                .map(|_| "tool_failed".to_string())
        });
    let safe_message = observation
        .get("message")
        .and_then(Value::as_str)
        .map(|value| redact_react_trace_text(value, ASSISTANT_RUN_REACT_MESSAGE_TRACE_LIMIT))
        .or_else(|| {
            observation
                .get("error")
                .and_then(Value::as_str)
                .map(|_| "工具执行失败".to_string())
        })
        .unwrap_or_default();

    json!({
        "status": status,
        "action_type": action_type,
        "denied_count": denied_count,
        "returned_count": returned_count,
        "detail_target_count": detail_target_count,
        "safe_error_code": safe_error_code,
        "safe_message": safe_message,
    })
}

fn assistant_run_react_returned_count(observation: &Value) -> usize {
    observation
        .get("items")
        .and_then(Value::as_array)
        .map(Vec::len)
        .or_else(|| {
            observation
                .get("supplied_items")
                .and_then(Value::as_array)
                .map(Vec::len)
        })
        .or_else(|| {
            observation
                .get("supplied_count")
                .and_then(Value::as_u64)
                .map(|value| value as usize)
        })
        .unwrap_or_default()
}

fn bounded_duration_ms(duration_ms: u128) -> u64 {
    duration_ms.min(u64::MAX as u128) as u64
}

fn redact_react_trace_text(raw: &str, max_chars: usize) -> String {
    let value = raw.trim().chars().take(max_chars).collect::<String>();
    let lower = value.to_ascii_lowercase();
    if lower.contains("secret")
        || lower.contains("token")
        || lower.contains("password")
        || lower.contains("api_key")
        || lower.contains("apikey")
        || lower.contains("authorization")
        || lower.contains("bearer ")
        || lower.contains("sk-")
    {
        "[redacted]".to_string()
    } else {
        value
    }
}

#[allow(dead_code)]
pub(crate) fn build_react_protocol_repair(
    decision: &AssistantRunNextAction,
    observations: &[Value],
    selected_scope: &Value,
    evidence_state: &Value,
) -> Option<AssistantRunReactActionResult> {
    build_react_protocol_repair_at_step(decision, observations, selected_scope, evidence_state, 0)
}

fn build_react_protocol_repair_at_step(
    decision: &AssistantRunNextAction,
    observations: &[Value],
    selected_scope: &Value,
    evidence_state: &Value,
    step_index: usize,
) -> Option<AssistantRunReactActionResult> {
    if assistant_run_react_should_repair_terminal_action(
        decision,
        selected_scope,
        evidence_state,
        observations,
    ) {
        return Some(assistant_run_react_policy_observation(
            decision,
            "final_answer requires a supply observation; choose a whitelisted action before answering.",
            step_index,
        ));
    }

    if decision.status == AssistantRunReActStatus::ReportChoice
        && !assistant_run_react_has_completed_action(observations, "list_report_options")
    {
        return Some(assistant_run_react_policy_observation(
            decision,
            "report_choice requires list_report_options observation before choosing a report path.",
            step_index,
        ));
    }

    if let Some(denied) = react_requested_scope_denial(decision, selected_scope) {
        return Some(build_assistant_run_react_policy_repair_result(
            decision,
            "requested dataset or document is outside the current selected scope.",
            step_index,
            vec![denied],
            "scope_denied",
        ));
    }

    if assistant_run_react_repeats_no_progress_action(decision, observations) {
        return Some(build_assistant_run_react_policy_repair_result(
            decision,
            "same no-progress action repeated; choose a different whitelisted action or cannot_answer.",
            step_index,
            vec![format!("repeated:{}", decision.action_type.as_str())],
            "repeated_no_progress_action",
        ));
    }

    None
}

fn build_assistant_run_react_policy_repair_result(
    action: &AssistantRunNextAction,
    message: &str,
    step_index: usize,
    denied: Vec<String>,
    repair_code: &str,
) -> AssistantRunReactActionResult {
    AssistantRunReactActionResult {
        observation: json!({
            "status": "rejected",
            "action_type": "policy_observation",
            "actionType": "policy_observation",
            "message": message,
            "denied": denied,
            "items": [],
            "limits": {},
            "repair_required": true,
            "repair_code": repair_code,
            "step": step_index,
        }),
        trail_step: json!({
            "status": "rejected",
            "label": "ReAct 协议修复",
            "react_action": action.action_type.as_str(),
            "message": message,
            "react_step": step_index,
            "at": Utc::now(),
        }),
        final_answer: None,
    }
}

fn assistant_run_react_should_repair_terminal_action(
    action: &AssistantRunNextAction,
    selected_scope: &Value,
    evidence_state: &Value,
    observations: &[Value],
) -> bool {
    action.action_type == AssistantRunReactActionType::FinalAnswer
        && assistant_run_react_scope_requires_supply(selected_scope)
        && !assistant_run_react_has_supply_observation(evidence_state, observations)
}

fn assistant_run_react_has_completed_action(observations: &[Value], action_type: &str) -> bool {
    observations.iter().any(|observation| {
        observation
            .get("status")
            .and_then(Value::as_str)
            .is_some_and(|status| status == "completed")
            && observation
                .get("action_type")
                .or_else(|| observation.get("actionType"))
                .and_then(Value::as_str)
                .is_some_and(|value| value == action_type)
    })
}

fn assistant_run_react_repeats_no_progress_action(
    decision: &AssistantRunNextAction,
    observations: &[Value],
) -> bool {
    let action_type = decision.action_type.as_str();
    observations
        .iter()
        .rev()
        .take(2)
        .filter(|observation| {
            observation
                .get("status")
                .and_then(Value::as_str)
                .is_some_and(|status| matches!(status, "rejected" | "failed" | "denied"))
                && observation
                    .get("action_type")
                    .or_else(|| observation.get("actionType"))
                    .and_then(Value::as_str)
                    .is_some_and(|value| value == action_type)
        })
        .count()
        >= 2
}

fn react_requested_scope_denial(
    decision: &AssistantRunNextAction,
    selected_scope: &Value,
) -> Option<String> {
    let requested_dataset_id = decision
        .arguments
        .get("dataset_id")
        .or_else(|| decision.arguments.get("datasetId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if let Some(requested_dataset_id) = requested_dataset_id {
        let selected_dataset_ids = selected_dataset_ids_from_scope(selected_scope);
        let requested = Uuid::parse_str(requested_dataset_id).ok().map(DatasetId);
        if requested.is_none_or(|requested| !selected_dataset_ids.contains(&requested)) {
            return Some(format!("dataset:{requested_dataset_id}"));
        }
    }

    let requested_document_id = decision
        .arguments
        .get("document_id")
        .or_else(|| decision.arguments.get("documentId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    if let Some(requested_document_id) = requested_document_id {
        let selected_document_ids = selected_document_ids_from_scope(selected_scope);
        let requested = Uuid::parse_str(requested_document_id).ok().map(DocumentId);
        if !selected_document_ids.is_empty()
            && requested.is_none_or(|requested| !selected_document_ids.contains(&requested))
        {
            return Some(format!("document:{requested_document_id}"));
        }
    }

    None
}

fn assistant_run_react_scope_requires_supply(selected_scope: &Value) -> bool {
    !selected_dataset_ids_from_scope(selected_scope).is_empty()
        || selected_scope_requests_conversation_memory(selected_scope)
}

fn assistant_run_react_has_supply_observation(
    evidence_state: &Value,
    observations: &[Value],
) -> bool {
    assistant_run_evidence_supplied_count(evidence_state) > 0
        || observations.iter().any(|observation| {
            observation
                .get("status")
                .and_then(Value::as_str)
                .is_some_and(|status| status == "completed")
                && observation
                    .get("action_type")
                    .and_then(Value::as_str)
                    .is_some_and(|action_type| {
                        matches!(
                            action_type,
                            "retrieve_evidence"
                                | "read_document_detail"
                                | "recall_conversation_memory"
                        )
                    })
        })
}

fn ensure_react_requested_dataset_is_selected(
    arguments: &Value,
    selected_scope: &Value,
) -> std::result::Result<(), ApiError> {
    let Some(requested_dataset_id) = arguments
        .get("dataset_id")
        .or_else(|| arguments.get("datasetId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    else {
        return Ok(());
    };
    let requested_dataset_id = Uuid::parse_str(requested_dataset_id)
        .map(DatasetId)
        .map_err(|_| {
            ApiError::bad_request("invalid_react_action", "dataset_id is invalid".to_string())
        })?;
    if selected_dataset_ids_from_scope(selected_scope)
        .into_iter()
        .any(|dataset_id| dataset_id == requested_dataset_id)
    {
        return Ok(());
    }
    Err(ApiError::bad_request(
        "react_dataset_not_selected",
        "ReAct retrieve_evidence can only use the current selected dataset scope".to_string(),
    ))
}

fn ensure_scope_requests_conversation_memory(mut selected_scope: Value) -> Value {
    ensure_json_object(&mut selected_scope);
    if let Some(object) = selected_scope.as_object_mut() {
        object
            .entry("conversation_memory".to_string())
            .or_insert_with(|| json!(["current_thread"]));
    }
    selected_scope
}

fn react_static_page_operations_from_arguments(
    arguments: &Value,
) -> std::result::Result<Vec<Value>, ApiError> {
    let operations = if let Some(operations) = arguments.get("operations").and_then(Value::as_array)
    {
        operations.clone()
    } else {
        let module_id = arguments
            .get("module_id")
            .or_else(|| arguments.get("moduleId"))
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .ok_or_else(|| {
                ApiError::bad_request(
                    "invalid_react_action",
                    "update_static_page_module requires module_id or operations".to_string(),
                )
            })?;
        let patch = arguments.get("patch").cloned().ok_or_else(|| {
            ApiError::bad_request(
                "invalid_react_action",
                "update_static_page_module requires patch or operations".to_string(),
            )
        })?;
        vec![json!({
            "type": "update_module",
            "targetModuleId": module_id,
            "patch": patch,
        })]
    };
    validate_static_page_operations(operations)
}

fn env_flag(key: &str, default_value: bool) -> bool {
    std::env::var(key)
        .ok()
        .map(|value| {
            matches!(
                value.trim().to_ascii_lowercase().as_str(),
                "1" | "true" | "yes" | "on"
            )
        })
        .unwrap_or(default_value)
}

fn normalize_assistant_run_continue_max_steps(value: Option<usize>) -> usize {
    value
        .unwrap_or(ASSISTANT_RUN_CONTINUE_DEFAULT_MAX_STEPS)
        .clamp(1, ASSISTANT_RUN_CONTINUE_MAX_STEPS)
}

async fn build_assistant_run_evidence_state(
    state: &AppState,
    selected_scope: &Value,
    prompt: &str,
    local_thread_id: Option<&str>,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
) -> std::result::Result<Value, ApiError> {
    let dataset_ids = selected_dataset_ids_from_scope(selected_scope);
    let conversation_memory_requested = selected_scope_requests_conversation_memory(selected_scope);
    if dataset_ids.is_empty() && !conversation_memory_requested {
        return Ok(json!({
            "status": "not_requested",
            "policy": "host_supplies_model_answers",
            "intent": assistant_run_scope_intent(selected_scope),
            "supply_policy": assistant_run_scope_supply_policy(selected_scope),
            "action_policy": assistant_run_scope_action_policy(selected_scope),
            "context_budget_policy": assistant_run_scope_context_budget_policy(selected_scope),
            "candidate_policy": assistant_run_scope_candidate_policy(selected_scope),
            "recommended_tool_actions": assistant_run_scope_recommended_tool_actions(selected_scope),
            "supplied_items": [],
        }));
    }

    let prefer_detail = assistant_run_scope_prefers_detail(selected_scope);
    let limit = assistant_run_evidence_limit_for_scope(selected_scope);
    let mut supplied_items = Vec::new();
    let mut supplied_datasets = Vec::new();
    let mut supplied_memory_items = Vec::new();
    let mut media_context_by_document: HashMap<DocumentId, Option<Value>> = HashMap::new();

    for dataset_id in dataset_ids
        .into_iter()
        .take(ASSISTANT_RUN_EVIDENCE_DATASET_LIMIT)
    {
        let dataset = load_visible_dataset_for_user(
            state,
            dataset_id,
            active_secret_binding_ids,
            current_user_id,
        )
        .await?;
        supplied_datasets.push(json!({
            "id": dataset.id,
            "key": dataset.key.clone(),
            "title": dataset.title.clone(),
            "visibility": dataset.visibility.as_str(),
        }));

        let evidences = state
            .storage
            .retrieval_evidences()
            .list_latest_by_dataset(
                state.tenant_id,
                dataset.id,
                retrieval_search_scan_limit(limit),
            )
            .await
            .map_err(ApiError::from_storage)?;
        let evidences = filter_retrieval_evidences_for_visible_documents(
            state,
            dataset.id,
            evidences,
            current_user_id,
        )
        .await?;

        let ranked_evidences = rank_retrieval_evidences_for_prompt(&evidences, prompt, limit);
        if ranked_evidences.is_empty() {
            let fallback_items = build_assistant_run_chunk_fallback_supply(
                state,
                &dataset,
                prompt,
                limit,
                current_user_id,
                &mut media_context_by_document,
            )
            .await?;
            supplied_items.extend(fallback_items);
            continue;
        }

        for ranked in ranked_evidences {
            let media_context = assistant_run_media_context_for_document(
                state,
                ranked.evidence.document_id,
                &mut media_context_by_document,
            )
            .await?;
            let mut supplied_item = json!({
                "type": "retrieval_evidence",
                "dataset_id": ranked.evidence.dataset_id,
                "document_id": ranked.evidence.document_id,
                "document_chunk_id": ranked.evidence.document_chunk_id,
                "retrieval_evidence_id": ranked.evidence.id,
                "chunk_index": ranked.evidence.chunk_index,
                "source_locator": ranked.evidence.source_locator.clone(),
                "summary": ranked.evidence.summary.clone(),
                "content_excerpt": ranked.evidence.content_excerpt.clone(),
                "payload_filter_key": ranked.evidence.payload_filter_key.clone(),
                "score": ranked.score,
                "lexical_score": ranked.lexical_score,
                "recall_score": ranked.recall_score,
                "evidence_manifest": ranked.evidence.evidence_manifest.clone(),
            });
            if let Some(media_context) = media_context {
                if let Some(object) = supplied_item.as_object_mut() {
                    object.insert("media_context".to_string(), media_context);
                }
            }
            supplied_items.push(supplied_item);
        }
    }

    if conversation_memory_requested {
        if let Some(local_thread_id) = local_thread_id
            .map(str::trim)
            .filter(|value| !value.is_empty())
        {
            let items = state
                .storage
                .conversation_memory_items()
                .list_by_local_thread(
                    state.tenant_id,
                    local_thread_id,
                    None,
                    assistant_run_conversation_memory_limit(),
                )
                .await
                .map_err(ApiError::from_storage)?;

            for item in items
                .into_iter()
                .filter(|item| owner_user_id_is_visible(item.user_id, current_user_id))
                .filter(assistant_run_memory_item_is_supply_eligible)
            {
                let supplied_item = json!({
                    "type": "conversation_memory_item",
                    "conversation_memory_item_id": item.id,
                    "local_thread_id": item.local_thread_id,
                    "role": item.role.as_str(),
                    "item_kind": item.item_kind,
                    "summary": item.summary,
                    "source_message_refs": item.source_message_refs,
                    "artifact_refs": item.artifact_refs,
                    "metadata": item.metadata,
                    "created_at": item.created_at,
                    "updated_at": item.updated_at,
                });
                supplied_memory_items.push(supplied_item.clone());
                supplied_items.push(supplied_item);
            }
        }
    }

    let status = if supplied_items.is_empty() {
        "empty"
    } else {
        "supplied"
    };
    let detail_targets = assistant_run_detail_targets_for_scope(selected_scope, &supplied_items);
    let fallback_supply_count = assistant_run_fallback_supply_count(&supplied_items);
    Ok(json!({
        "status": status,
        "policy": "host_supplies_model_answers",
        "intent": assistant_run_scope_intent(selected_scope),
        "supply_policy": assistant_run_scope_supply_policy(selected_scope),
        "action_policy": assistant_run_scope_action_policy(selected_scope),
        "context_budget_policy": assistant_run_scope_context_budget_policy(selected_scope),
        "candidate_policy": assistant_run_scope_candidate_policy(selected_scope),
        "detail_preferred": prefer_detail,
        "recommended_tool_actions": assistant_run_scope_recommended_tool_actions(selected_scope),
        "recommended_actions": assistant_run_recommended_supply_actions(selected_scope, !supplied_items.is_empty()),
        "detail_targets": detail_targets,
        "selected_scope": selected_scope,
        "datasets": supplied_datasets,
        "conversation_memory_items": supplied_memory_items,
        "supplied_items": supplied_items,
        "fallback_supply_count": fallback_supply_count,
        "fallback_supply_policy": if fallback_supply_count > 0 { "visible_document_chunks_when_retrieval_evidence_missing" } else { "not_used" },
        "limit": limit,
    }))
}

async fn build_assistant_run_chunk_fallback_supply(
    state: &AppState,
    dataset: &Dataset,
    prompt: &str,
    limit: usize,
    current_user_id: Option<UserId>,
    media_context_by_document: &mut HashMap<DocumentId, Option<Value>>,
) -> std::result::Result<Vec<Value>, ApiError> {
    if limit == 0 {
        return Ok(Vec::new());
    }

    let documents = state
        .storage
        .documents()
        .list_by_dataset(state.tenant_id, dataset.id)
        .await
        .map_err(ApiError::from_storage)?
        .into_iter()
        .filter(|document| owner_user_id_is_visible(document.owner_user_id, current_user_id))
        .collect::<Vec<_>>();
    let mut sources = Vec::new();
    for document in documents {
        let chunks = state
            .storage
            .document_chunks()
            .list_by_document(state.tenant_id, document.id)
            .await
            .map_err(ApiError::from_storage)?;
        for chunk in chunks
            .into_iter()
            .filter(|chunk| !chunk.content.trim().is_empty())
        {
            sources.push((document.clone(), chunk));
        }
    }

    let ranked = rank_document_chunks_for_prompt(sources, prompt, limit);
    let mut items = Vec::with_capacity(ranked.len());
    for ranked in ranked {
        let media_context = assistant_run_media_context_for_document(
            state,
            ranked.chunk.document_id,
            media_context_by_document,
        )
        .await?;
        let mut supplied_item = json!({
            "type": "retrieval_evidence",
            "source": "document_chunk_fallback",
            "fallback_reason": "retrieval_evidence_unavailable",
            "dataset_id": ranked.chunk.dataset_id,
            "document_id": ranked.chunk.document_id,
            "document_chunk_id": ranked.chunk.id,
            "chunk_index": ranked.chunk.chunk_index,
            "source_locator": document_chunk_fallback_source_locator(&ranked.document, &ranked.chunk),
            "summary": document_chunk_fallback_summary(&ranked.document, &ranked.chunk),
            "content_excerpt": truncate_assistant_supply_text(&ranked.chunk.content, 900),
            "payload_filter_key": format!("dataset/{}/document/{}", dataset.key, ranked.document.object_key),
            "score": ranked.score,
            "lexical_score": ranked.lexical_score,
            "recall_score": 0.0,
            "evidence_manifest": {
                "fallback": {
                    "source": "document_chunk",
                    "reason": "retrieval_evidence_unavailable"
                },
                "embedding": {
                    "term_weights": limited_lexical_term_weights(&ranked.search_text, 40)
                }
            },
        });
        if let Some(media_context) = media_context {
            if let Some(object) = supplied_item.as_object_mut() {
                object.insert("media_context".to_string(), media_context);
            }
        }
        items.push(supplied_item);
    }
    Ok(items)
}

fn assistant_run_evidence_limit_for_scope(selected_scope: &Value) -> usize {
    if assistant_run_scope_prefers_detail(selected_scope)
        && !selected_dataset_ids_from_scope(selected_scope).is_empty()
    {
        ASSISTANT_RUN_EVIDENCE_MAX_LIMIT
    } else {
        assistant_run_evidence_limit()
    }
}

fn assistant_run_evidence_limit() -> usize {
    std::env::var("ASSISTANT_RUN_EVIDENCE_LIMIT")
        .ok()
        .and_then(|value| value.parse::<usize>().ok())
        .unwrap_or(ASSISTANT_RUN_EVIDENCE_DEFAULT_LIMIT)
        .clamp(1, ASSISTANT_RUN_EVIDENCE_MAX_LIMIT)
}

fn assistant_run_recommended_supply_actions(
    selected_scope: &Value,
    has_supplied_items: bool,
) -> Vec<&'static str> {
    let mut actions = Vec::new();
    if !selected_dataset_ids_from_scope(selected_scope).is_empty() {
        actions.push("retrieve_evidence");
        if assistant_run_scope_prefers_detail(selected_scope) && has_supplied_items {
            actions.push("read_document_detail");
        }
    }
    if selected_scope_requests_conversation_memory(selected_scope) {
        actions.push("recall_conversation_memory");
    }
    match assistant_run_scope_intent(selected_scope) {
        "static_page" => actions.push("create_static_page_draft"),
        "report" => actions.push("list_report_options"),
        _ => {}
    }
    actions
}

fn assistant_run_fallback_supply_count(supplied_items: &[Value]) -> usize {
    supplied_items
        .iter()
        .filter(|item| {
            item.get("source")
                .and_then(Value::as_str)
                .is_some_and(|source| source == "document_chunk_fallback")
        })
        .count()
}

fn document_chunk_fallback_source_locator(document: &Document, chunk: &DocumentChunk) -> String {
    let base = if document.object_key.trim().is_empty() {
        document.title.trim()
    } else {
        document.object_key.trim()
    };
    format!("{}#chunk={}", base, chunk.chunk_index)
}

fn document_chunk_fallback_summary(document: &Document, chunk: &DocumentChunk) -> String {
    let title = if document.title.trim().is_empty() {
        document.object_key.trim()
    } else {
        document.title.trim()
    };
    let excerpt = truncate_assistant_supply_text(&chunk.content, 180);
    if excerpt.is_empty() {
        format!("{title} chunk {}", chunk.chunk_index)
    } else {
        format!("{title} chunk {}: {excerpt}", chunk.chunk_index)
    }
}

fn truncate_assistant_supply_text(value: &str, max_chars: usize) -> String {
    value
        .trim()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .chars()
        .take(max_chars)
        .collect()
}

fn assistant_run_detail_targets_for_scope(
    selected_scope: &Value,
    supplied_items: &[Value],
) -> Vec<Value> {
    if !assistant_run_scope_prefers_detail(selected_scope) {
        return Vec::new();
    }

    let mut seen_documents = HashSet::new();
    supplied_items
        .iter()
        .filter(|item| {
            item.get("type")
                .and_then(Value::as_str)
                .is_some_and(|item_type| item_type == "retrieval_evidence")
        })
        .filter_map(|item| {
            let document_id = item.get("document_id").or_else(|| item.get("documentId"))?;
            let document_key = document_id
                .as_str()
                .map(ToString::to_string)
                .unwrap_or_else(|| document_id.to_string());
            if document_key.trim().is_empty() || !seen_documents.insert(document_key) {
                return None;
            }

            let media_context = item
                .get("media_context")
                .or_else(|| item.get("mediaContext"));
            let has_media_context = media_context.is_some_and(Value::is_object);
            let has_timestamped_evidence = media_context
                .and_then(|context| context.get("has_timestamped_evidence"))
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let reason = if has_timestamped_evidence {
                "timestamped_media_detail_available"
            } else if has_media_context {
                "media_detail_available"
            } else {
                "detail_first_scope"
            };

            let mut target = Map::new();
            target.insert("type".to_string(), json!("document_detail_target"));
            for key in [
                "dataset_id",
                "datasetId",
                "document_id",
                "documentId",
                "retrieval_evidence_id",
                "retrievalEvidenceId",
                "chunk_index",
                "chunkIndex",
                "source_locator",
                "sourceLocator",
            ] {
                if let Some(value) = item.get(key).filter(|value| !value.is_null()) {
                    target.insert(key.to_string(), value.clone());
                }
            }
            target.insert("reason".to_string(), json!(reason));
            target.insert("has_media_context".to_string(), json!(has_media_context));
            target.insert(
                "has_timestamped_evidence".to_string(),
                json!(has_timestamped_evidence),
            );
            Some(Value::Object(target))
        })
        .take(ASSISTANT_RUN_DETAIL_TARGET_LIMIT)
        .collect()
}

async fn assistant_run_media_context_for_document(
    state: &AppState,
    document_id: DocumentId,
    cache: &mut HashMap<DocumentId, Option<Value>>,
) -> std::result::Result<Option<Value>, ApiError> {
    if let Some(cached) = cache.get(&document_id) {
        return Ok(cached.clone());
    }

    let chunks = state
        .storage
        .document_chunks()
        .list_by_document(state.tenant_id, document_id)
        .await
        .map_err(ApiError::from_storage)?;
    let context = extract_media_metadata_from_chunks(&chunks)
        .as_ref()
        .and_then(build_assistant_run_media_supply_context);
    cache.insert(document_id, context.clone());
    Ok(context)
}

fn build_assistant_run_media_supply_context(raw_media_metadata: &Value) -> Option<Value> {
    let media_kind = raw_media_metadata
        .get("kind")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let parse_status = raw_media_metadata
        .get("parse_status")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let transcript_windows = collect_media_transcript_segments(raw_media_metadata)
        .into_iter()
        .take(3)
        .collect::<Vec<_>>();
    let scene_windows = collect_media_scenes(raw_media_metadata)
        .into_iter()
        .take(3)
        .collect::<Vec<_>>();
    let keyframe_ocr_snippets = collect_media_ocr_snippets(raw_media_metadata)
        .into_iter()
        .take(3)
        .collect::<Vec<_>>();
    let provider_evidence = collect_media_provider_evidence(raw_media_metadata)
        .into_iter()
        .take(3)
        .collect::<Vec<_>>();
    let has_timestamped_evidence = !transcript_windows.is_empty()
        || !scene_windows.is_empty()
        || !keyframe_ocr_snippets.is_empty();
    let has_context = has_timestamped_evidence
        || !provider_evidence.is_empty()
        || !matches!(media_kind, "unknown" | "");
    if !has_context {
        return None;
    }

    Some(json!({
        "media_kind": media_kind,
        "parse_status": parse_status,
        "has_timestamped_evidence": has_timestamped_evidence,
        "transcript_windows": transcript_windows,
        "scene_windows": scene_windows,
        "keyframe_ocr_snippets": keyframe_ocr_snippets,
        "provider_evidence": provider_evidence,
    }))
}

fn assistant_run_artifact_scope_candidates(
    client_candidates: &[Value],
    current_artifact: Option<&Value>,
) -> Vec<Value> {
    let Some(current_artifact) = current_artifact else {
        return Vec::new();
    };
    let Some(artifact_id) = static_page_artifact_id(current_artifact) else {
        return Vec::new();
    };
    let client_static_page_candidate = client_candidates.iter().find(|candidate| {
        candidate.get("type").and_then(Value::as_str) == Some("static_page_draft")
            && candidate.get("id").and_then(Value::as_str) == Some(artifact_id.as_str())
    });
    let label = static_page_artifact_label(current_artifact)
        .or_else(|| {
            client_static_page_candidate
                .and_then(|candidate| candidate.get("label"))
                .and_then(Value::as_str)
                .map(truncate_scope_candidate_text)
        })
        .unwrap_or_else(|| "当前静态页草稿".to_string());

    vec![json!({
        "type": "static_page_draft",
        "id": artifact_id,
        "label": label,
        "confidence": "high",
        "reason": "当前主区域打开了静态页草稿",
        "source": "active_artifact",
    })]
}

fn static_page_artifact_id(artifact: &Value) -> Option<String> {
    ["backendDraftId", "backend_draft_id", "backendId", "id"]
        .iter()
        .find_map(|key| {
            artifact
                .get(*key)
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToString::to_string)
        })
}

fn static_page_artifact_label(artifact: &Value) -> Option<String> {
    ["objective", "title"].iter().find_map(|key| {
        artifact
            .get(*key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(|value| format!("当前静态页：{}", truncate_scope_candidate_text(value)))
    })
}

fn truncate_scope_candidate_text(value: &str) -> String {
    value.chars().take(80).collect()
}

fn dedupe_assistant_run_scope_candidate_values(candidates: Vec<Value>) -> Vec<Value> {
    let mut seen = HashSet::new();
    candidates
        .into_iter()
        .filter(|candidate| {
            let candidate_type = candidate.get("type").and_then(Value::as_str).unwrap_or("");
            let id = candidate.get("id").and_then(Value::as_str).unwrap_or("");
            if candidate_type.is_empty() || id.is_empty() {
                return true;
            }
            seen.insert(format!("{candidate_type}:{id}"))
        })
        .collect()
}

fn assistant_run_conversation_memory_limit() -> i64 {
    std::env::var("ASSISTANT_RUN_CONVERSATION_MEMORY_LIMIT")
        .ok()
        .and_then(|value| value.parse::<i64>().ok())
        .unwrap_or(ASSISTANT_RUN_CONVERSATION_MEMORY_DEFAULT_LIMIT)
        .clamp(1, ASSISTANT_RUN_CONVERSATION_MEMORY_MAX_LIMIT)
}

fn assistant_run_memory_item_is_supply_eligible(item: &ConversationMemoryItem) -> bool {
    item.role == ChatMessageRole::User
        && !matches!(
            item.item_kind.as_str(),
            "assistant_output" | "artifact_output" | "generated_artifact"
        )
}

fn assistant_run_evidence_supplied_count(evidence_state: &Value) -> usize {
    evidence_state
        .get("supplied_items")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0)
}

fn assistant_run_detail_target_count(evidence_state: &Value) -> usize {
    evidence_state
        .get("detail_targets")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0)
}

fn assistant_run_evidence_status_label(evidence_state: &Value) -> String {
    let status = evidence_state
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    match status {
        "supplied" => {
            let supplied_count = assistant_run_evidence_supplied_count(evidence_state);
            let detail_target_count = assistant_run_detail_target_count(evidence_state);
            let fallback_supply_count = evidence_state
                .get("fallback_supply_count")
                .and_then(Value::as_u64)
                .unwrap_or(0);
            if fallback_supply_count > 0 {
                if detail_target_count > 0 {
                    return format!(
                        "已供料 {supplied_count} 条，其中 {fallback_supply_count} 条来自可见文档切片兜底，建议深读 {detail_target_count} 份文档"
                    );
                }
                return format!(
                    "已供料 {supplied_count} 条，其中 {fallback_supply_count} 条来自可见文档切片兜底"
                );
            }
            if detail_target_count > 0 {
                format!("已检索 {supplied_count} 条供料项，建议深读 {detail_target_count} 份文档")
            } else {
                format!("已检索 {supplied_count} 条供料项")
            }
        }
        "empty" => "已请求供料，但暂未检索到可用内容".to_string(),
        "not_requested" => "未请求数据集供料".to_string(),
        other => other.to_string(),
    }
}

