fn build_static_page_render_spec() -> Value {
    json!({
        "renderer": "static-page-renderer-v1",
        "layoutEngine": "css-grid-12",
        "desktopGrid": {
            "columns": 12,
            "rowHeight": 96
        },
        "mobileLayout": "single-column-sortable",
        "componentModel": "dom-text-svg-chart",
        "chartRuntime": "deterministic-with-echarts-advanced",
        "chartRuntimePolicy": {
            "default": "deterministic",
            "advanced": "echarts",
            "allowedRuntimes": ["deterministic", "echarts"],
            "advancedOptions": "plain-json-echarts-option-only",
            "finalRendererFallback": "ECharts modules must still have dataSnapshot sampleData so the final renderer can fall back to deterministic DOM/SVG output.",
            "advancedHydration": "Final HTML preserves safe ECharts JSON option islands; if an approved ECharts bundle is present, the page can hydrate charts without losing deterministic fallback."
        },
        "editableContent": ["title", "content", "dataBinding", "visualization", "chartRuntime", "chartOptions", "layout"],
        "generationGuardrails": [
            "效果图必须服从模块网格布局和移动端顺序",
            "正文、指标、图表在最终静态页中必须是真 DOM 或 SVG，不允许只烘焙进图片",
            "复杂背景、纹理、装饰可以作为图片资产，核心数据表达必须可重新渲染",
            "ECharts 只允许纯 JSON 配置，不允许函数、HTML、远程 URL 或事件处理器字段",
            "避免 3D 透视、真实摄影 UI、不可复刻字体效果和过度复杂玻璃反射"
        ]
    })
}

fn build_static_page_data_snapshot(payload: &Value, selected_scope: &Value) -> Value {
    let evidence_state = payload
        .get("assistant_context")
        .and_then(|context| context.get("evidence_state"));
    build_static_page_data_snapshot_with_evidence(
        payload,
        selected_scope,
        evidence_state,
        "static_page_draft",
    )
}

fn build_static_page_data_snapshot_with_evidence(
    payload: &Value,
    selected_scope: &Value,
    evidence_state: Option<&Value>,
    source: &str,
) -> Value {
    let data_source_candidates = build_static_page_data_source_candidates(selected_scope);
    let field_candidates = build_static_page_field_candidates(selected_scope, evidence_state);
    let module_bindings = static_page_payload_modules(payload)
        .as_array()
        .cloned()
        .unwrap_or_default()
        .into_iter()
        .map(|module| {
            let sample_data = build_static_page_module_sample_data(&module, evidence_state);
            let data_quality = static_page_sample_data_quality(&sample_data);
            json!({
                "moduleId": module.get("id").cloned().unwrap_or(Value::Null),
                "title": module.get("title").cloned().unwrap_or(Value::Null),
                "binding": module
                    .get("dataBinding")
                    .or_else(|| module.get("data_binding"))
                    .cloned()
                    .unwrap_or(Value::Null),
                "visualizationType": module
                    .get("visualization")
                    .and_then(|visualization| visualization.get("type"))
                    .cloned()
                    .unwrap_or_else(|| json!("text-insight")),
                "chartRuntime": static_page_module_chart_runtime(&module),
                "chartOptions": module
                    .get("visualization")
                    .and_then(|visualization| visualization.get("chartOptions"))
                    .or_else(|| module.get("chartOptions"))
                    .cloned()
                    .unwrap_or_else(|| json!({})),
                "sampleData": sample_data,
                "dataQuality": data_quality,
            })
        })
        .collect::<Vec<_>>();
    json!({
        "version": 1,
        "source": source,
        "selected_scope": selected_scope,
        "evidence_status": evidence_state
            .and_then(|state| state.get("status"))
            .cloned()
            .unwrap_or(Value::Null),
        "data_source_candidates": data_source_candidates,
        "field_candidates": field_candidates,
        "module_bindings": module_bindings,
    })
}

fn build_static_page_data_source_candidates(selected_scope: &Value) -> Value {
    let mut candidates = vec![
        json!({
            "sourceId": "model",
            "type": "model_summary",
            "label": "模型总结",
            "available": true,
        }),
        json!({
            "sourceId": "conversation_memory",
            "type": "conversation_memory",
            "label": "对话历史",
            "available": selected_scope_requests_conversation_memory(selected_scope),
        }),
    ];

    let selected_dataset_ids = selected_dataset_ids_from_scope(selected_scope);
    if !selected_dataset_ids.is_empty() {
        candidates.push(json!({
            "sourceId": "selected_scope",
            "type": "selected_scope",
            "label": "当前选中范围",
            "available": true,
            "datasetIds": selected_dataset_ids.iter().map(ToString::to_string).collect::<Vec<_>>(),
        }));
        candidates.push(json!({
            "sourceId": "dataset",
            "type": "dataset_metrics",
            "label": "数据集指标摘要",
            "available": true,
            "datasetIds": selected_dataset_ids.iter().map(ToString::to_string).collect::<Vec<_>>(),
        }));
        candidates.push(json!({
            "sourceId": "evidence",
            "type": "retrieval_evidence",
            "label": "检索证据",
            "available": true,
            "datasetIds": selected_dataset_ids.iter().map(ToString::to_string).collect::<Vec<_>>(),
        }));
    }

    Value::Array(candidates)
}

fn build_static_page_field_candidates(
    selected_scope: &Value,
    evidence_state: Option<&Value>,
) -> Value {
    const FIELD_CANDIDATE_LIMIT: usize = 16;

    let mut candidates = Vec::new();
    let mut seen = BTreeSet::new();
    let selected_dataset_ids = selected_dataset_ids_from_scope(selected_scope);
    if !selected_dataset_ids.is_empty() {
        push_static_page_field_candidate(
            &mut candidates,
            &mut seen,
            json!({
                "sourceId": "dataset",
                "fieldPath": "dataset.metrics_summary",
                "label": "数据集指标摘要",
                "kind": "summary",
                "recommendedAggregation": Value::Null,
                "confidence": 0.55,
                "datasetIds": selected_dataset_ids.iter().map(ToString::to_string).collect::<Vec<_>>(),
            }),
            FIELD_CANDIDATE_LIMIT,
        );
    }

    let Some(evidence_items) = evidence_state
        .and_then(|state| state.get("supplied_items"))
        .and_then(Value::as_array)
    else {
        return Value::Array(candidates);
    };

    for item in evidence_items {
        match item.get("type").and_then(Value::as_str).unwrap_or_default() {
            "retrieval_evidence" => {
                let evidence_ref = static_page_evidence_ref(item);
                let evidence_ids = static_page_evidence_ids(item);
                push_static_page_field_candidate(
                    &mut candidates,
                    &mut seen,
                    json!({
                        "sourceId": "evidence",
                        "fieldPath": "retrieval.summary",
                        "label": "证据摘要",
                        "kind": "text",
                        "recommendedAggregation": Value::Null,
                        "confidence": 0.72,
                        "evidenceIds": evidence_ids,
                        "evidenceRef": evidence_ref,
                    }),
                    FIELD_CANDIDATE_LIMIT,
                );
                push_static_page_field_candidate(
                    &mut candidates,
                    &mut seen,
                    json!({
                        "sourceId": "evidence",
                        "fieldPath": "retrieval.content_excerpt",
                        "label": "证据原文片段",
                        "kind": "text",
                        "recommendedAggregation": Value::Null,
                        "confidence": 0.70,
                        "evidenceIds": static_page_evidence_ids(item),
                        "evidenceRef": static_page_evidence_ref(item),
                    }),
                    FIELD_CANDIDATE_LIMIT,
                );

                if let Some(media_context) =
                    item.get("media_context").filter(|value| value.is_object())
                {
                    push_static_page_media_field_candidates(
                        &mut candidates,
                        &mut seen,
                        media_context,
                        item,
                        FIELD_CANDIDATE_LIMIT,
                    );
                }

                let evidence_text = static_page_evidence_text(item).to_lowercase();
                for (field_path, label, kind, aggregation, keywords, confidence) in [
                    (
                        "orders.amount",
                        "订单金额/收入",
                        "metric",
                        Some("sum"),
                        &[
                            "order", "orders", "amount", "revenue", "sales", "gmv", "订单", "金额",
                            "收入",
                        ][..],
                        0.84,
                    ),
                    (
                        "orders.count",
                        "订单数量",
                        "metric",
                        Some("count"),
                        &["order", "orders", "count", "volume", "订单", "数量", "单量"][..],
                        0.78,
                    ),
                    (
                        "customers.count",
                        "客户数量",
                        "metric",
                        Some("count"),
                        &["customer", "customers", "client", "客户", "用户"][..],
                        0.76,
                    ),
                    (
                        "profit.margin",
                        "利润/毛利",
                        "metric",
                        Some("sum"),
                        &["profit", "margin", "gross", "利润", "毛利"][..],
                        0.76,
                    ),
                    (
                        "risk.level",
                        "风险等级",
                        "dimension",
                        None,
                        &["risk", "delay", "warning", "风险", "延期", "预警"][..],
                        0.80,
                    ),
                    (
                        "time.month",
                        "月份/时间",
                        "dimension",
                        None,
                        &[
                            "month", "date", "time", "period", "月份", "日期", "时间", "周期",
                        ][..],
                        0.72,
                    ),
                    (
                        "engagement.rate",
                        "触达/互动",
                        "metric",
                        Some("avg"),
                        &[
                            "engagement",
                            "newsletter",
                            "open",
                            "click",
                            "触达",
                            "互动",
                            "打开",
                            "点击",
                        ][..],
                        0.70,
                    ),
                ] {
                    if !static_page_text_contains_any(&evidence_text, keywords) {
                        continue;
                    }
                    push_static_page_field_candidate(
                        &mut candidates,
                        &mut seen,
                        json!({
                            "sourceId": "evidence",
                            "fieldPath": field_path,
                            "label": label,
                            "kind": kind,
                            "recommendedAggregation": aggregation,
                            "confidence": confidence,
                            "evidenceIds": static_page_evidence_ids(item),
                            "evidenceRef": static_page_evidence_ref(item),
                        }),
                        FIELD_CANDIDATE_LIMIT,
                    );
                }
            }
            "conversation_memory_item" => {
                push_static_page_field_candidate(
                    &mut candidates,
                    &mut seen,
                    json!({
                        "sourceId": "conversation_memory",
                        "fieldPath": "conversation.summary",
                        "label": "相关历史对话摘要",
                        "kind": "text",
                        "recommendedAggregation": Value::Null,
                        "confidence": 0.66,
                        "conversationMemoryItemId": item
                            .get("conversation_memory_item_id")
                            .cloned()
                            .unwrap_or(Value::Null),
                    }),
                    FIELD_CANDIDATE_LIMIT,
                );
            }
            _ => {}
        }
    }

    Value::Array(candidates)
}

fn push_static_page_media_field_candidates(
    candidates: &mut Vec<Value>,
    seen: &mut BTreeSet<String>,
    media_context: &Value,
    item: &Value,
    limit: usize,
) {
    for (key, field_path, label, confidence) in [
        (
            "transcript_windows",
            "media.transcript_windows",
            "媒体转写时间窗",
            0.82,
        ),
        (
            "scene_windows",
            "media.scene_windows",
            "视频场景时间窗",
            0.78,
        ),
        (
            "keyframe_ocr_snippets",
            "media.keyframe_ocr_snippets",
            "关键帧 OCR 片段",
            0.76,
        ),
    ] {
        let has_items = media_context
            .get(key)
            .and_then(Value::as_array)
            .is_some_and(|items| !items.is_empty());
        if !has_items {
            continue;
        }
        push_static_page_field_candidate(
            candidates,
            seen,
            json!({
                "sourceId": "evidence",
                "fieldPath": field_path,
                "label": label,
                "kind": "media",
                "recommendedAggregation": Value::Null,
                "confidence": confidence,
                "evidenceIds": static_page_evidence_ids(item),
                "evidenceRef": static_page_evidence_ref(item),
                "mediaKind": media_context
                    .get("media_kind")
                    .cloned()
                    .unwrap_or_else(|| json!("unknown")),
                "timestamped": media_context
                    .get("has_timestamped_evidence")
                    .cloned()
                    .unwrap_or_else(|| json!(false)),
            }),
            limit,
        );
    }
}

fn build_static_page_module_sample_data(module: &Value, evidence_state: Option<&Value>) -> Value {
    let field_path = static_page_module_field_path(module);
    let explicit_points = build_static_page_module_explicit_points(module, field_path);
    if !explicit_points.is_empty() {
        return Value::Array(explicit_points);
    }
    let Some(field_path) = field_path else {
        return json!([]);
    };
    let Some(evidence_items) = evidence_state
        .and_then(|state| state.get("supplied_items"))
        .and_then(Value::as_array)
    else {
        return json!([]);
    };
    if field_path.starts_with("media.") {
        let media_points = build_static_page_media_sample_points(evidence_items, field_path);
        if !media_points.is_empty() {
            return Value::Array(media_points);
        }
    }

    let keywords = static_page_field_keywords(field_path);
    if keywords.is_empty() {
        return json!([]);
    }

    let explicit_points =
        build_static_page_explicit_metric_points(evidence_items, field_path, &keywords);
    if !explicit_points.is_empty() {
        return Value::Array(explicit_points);
    }

    let points = evidence_items
        .iter()
        .filter(|item| {
            item.get("type").and_then(Value::as_str).unwrap_or_default() == "retrieval_evidence"
        })
        .enumerate()
        .filter_map(|(index, item)| {
            let value = static_page_keyword_signal_score(item, &keywords);
            if value <= 0.0 {
                return None;
            }
            Some(json!({
                "label": static_page_evidence_point_label(item, index),
                "value": value,
                "kind": "evidence_signal",
                "fieldPath": field_path,
                "evidenceIds": static_page_evidence_ids(item),
            }))
        })
        .take(6)
        .collect::<Vec<_>>();
    Value::Array(points)
}

fn static_page_module_field_path(module: &Value) -> Option<&str> {
    module
        .get("dataBinding")
        .or_else(|| module.get("data_binding"))
        .and_then(|binding| {
            binding
                .get("fieldPath")
                .or_else(|| binding.get("field_path"))
                .or_else(|| binding.get("field"))
        })
        .or_else(|| {
            module
                .get("visualization")
                .and_then(|visualization| visualization.get("chartOptions"))
                .and_then(|chart_options| chart_options.get("dataKey"))
        })
        .or_else(|| {
            module
                .get("chartOptions")
                .and_then(|chart_options| chart_options.get("dataKey"))
        })
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn build_static_page_media_sample_points(evidence_items: &[Value], field_path: &str) -> Vec<Value> {
    let Some(array_key) = static_page_media_sample_array_key(field_path) else {
        return Vec::new();
    };
    evidence_items
        .iter()
        .filter(|item| {
            item.get("type").and_then(Value::as_str).unwrap_or_default() == "retrieval_evidence"
        })
        .flat_map(|item| {
            item.get("media_context")
                .and_then(|context| context.get(array_key))
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .filter_map(move |window| {
                    let text = static_page_media_sample_text(window, array_key)?;
                    let start_seconds = media_numeric_field(
                        window,
                        &["start_seconds", "start", "timestamp_seconds", "timestamp"],
                    );
                    let end_seconds = media_numeric_field(window, &["end_seconds", "end"]);
                    let timestamp_label =
                        static_page_media_timestamp_label(start_seconds, end_seconds);
                    let citation_label =
                        static_page_media_citation_label(item, timestamp_label.as_deref());
                    Some(json!({
                        "label": static_page_media_sample_label(window, array_key),
                        "value": 1.0,
                        "kind": "media_window",
                        "fieldPath": field_path,
                        "text": text,
                        "startSeconds": start_seconds,
                        "endSeconds": end_seconds,
                        "timestampLabel": timestamp_label,
                        "citationLabel": citation_label,
                        "source": media_string_field(window, &["source"]).unwrap_or_else(|| "media".to_string()),
                        "sourceLocator": item.get("source_locator").cloned().unwrap_or(Value::Null),
                        "evidenceIds": static_page_evidence_ids(item),
                        "evidenceRef": static_page_evidence_ref(item),
                    }))
                })
                .collect::<Vec<_>>()
        })
        .take(6)
        .collect()
}

fn static_page_media_sample_array_key(field_path: &str) -> Option<&'static str> {
    let normalized = field_path.to_ascii_lowercase();
    if normalized.contains("media.transcript") {
        Some("transcript_windows")
    } else if normalized.contains("media.scene") {
        Some("scene_windows")
    } else if normalized.contains("media.keyframe") || normalized.contains("media.ocr") {
        Some("keyframe_ocr_snippets")
    } else {
        None
    }
}

fn static_page_media_sample_text(window: &Value, array_key: &str) -> Option<String> {
    match array_key {
        "scene_windows" => media_string_field(window, &["summary", "label"]),
        _ => media_string_field(window, &["text", "content", "summary"]),
    }
}

fn static_page_media_sample_label(window: &Value, array_key: &str) -> String {
    let timestamp = media_numeric_field(
        window,
        &["start_seconds", "start", "timestamp_seconds", "timestamp"],
    );
    let prefix = match array_key {
        "scene_windows" => "场景",
        "keyframe_ocr_snippets" => "关键帧",
        _ => "转写",
    };
    timestamp
        .map(|seconds| format!("{prefix} {:.1}s", seconds))
        .unwrap_or_else(|| prefix.to_string())
}

fn static_page_media_timestamp_label(
    start_seconds: Option<f64>,
    end_seconds: Option<f64>,
) -> Option<String> {
    match (start_seconds, end_seconds) {
        (Some(start), Some(end)) => Some(format!(
            "{} - {}",
            static_page_format_media_timestamp(start),
            static_page_format_media_timestamp(end)
        )),
        (Some(start), None) => Some(static_page_format_media_timestamp(start)),
        (None, Some(end)) => Some(static_page_format_media_timestamp(end)),
        (None, None) => None,
    }
}

fn static_page_media_citation_label(item: &Value, timestamp_label: Option<&str>) -> String {
    let source = item
        .get("source_locator")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("media");
    timestamp_label
        .map(|label| format!("{source} @ {label}"))
        .unwrap_or_else(|| source.to_string())
}

fn static_page_format_media_timestamp(seconds: f64) -> String {
    let safe_seconds = seconds.max(0.0);
    let total = safe_seconds.floor() as u64;
    let millis = ((safe_seconds - total as f64) * 1000.0).round() as u64;
    let hours = total / 3600;
    let minutes = (total % 3600) / 60;
    let secs = total % 60;
    if hours > 0 {
        format!("{hours:02}:{minutes:02}:{secs:02}.{millis:03}")
    } else {
        format!("{minutes:02}:{secs:02}.{millis:03}")
    }
}

fn static_page_module_chart_runtime(module: &Value) -> &'static str {
    let runtime = module
        .get("visualization")
        .and_then(|visualization| {
            visualization
                .get("chartRuntime")
                .or_else(|| visualization.get("runtime"))
                .or_else(|| {
                    visualization
                        .get("chartOptions")
                        .and_then(|chart_options| chart_options.get("chartRuntime"))
                })
                .or_else(|| {
                    visualization
                        .get("chartOptions")
                        .and_then(|chart_options| chart_options.get("runtime"))
                })
        })
        .or_else(|| module.get("chartRuntime"))
        .or_else(|| {
            module
                .get("chartOptions")
                .and_then(|chart_options| chart_options.get("chartRuntime"))
        })
        .and_then(Value::as_str)
        .map(str::trim);
    match runtime {
        Some("echarts") => "echarts",
        _ => "deterministic",
    }
}

fn build_static_page_module_explicit_points(
    module: &Value,
    field_path: Option<&str>,
) -> Vec<Value> {
    for candidate in static_page_module_explicit_data_candidates(module) {
        let points = static_page_explicit_points_from_value(candidate, field_path);
        if !points.is_empty() {
            return points;
        }
    }
    Vec::new()
}

fn static_page_module_explicit_data_candidates(module: &Value) -> Vec<&Value> {
    let mut candidates = Vec::new();
    if let Some(visualization) = module.get("visualization") {
        for key in [
            "sampleData",
            "sample_data",
            "data",
            "values",
            "rows",
            "items",
        ] {
            if let Some(value) = visualization.get(key) {
                candidates.push(value);
            }
        }
    }
    if let Some(binding) = module
        .get("dataBinding")
        .or_else(|| module.get("data_binding"))
    {
        for key in [
            "sampleData",
            "sample_data",
            "data",
            "values",
            "rows",
            "items",
        ] {
            if let Some(value) = binding.get(key) {
                candidates.push(value);
            }
        }
    }
    for key in [
        "sampleData",
        "sample_data",
        "data",
        "values",
        "rows",
        "items",
    ] {
        if let Some(value) = module.get(key) {
            candidates.push(value);
        }
    }
    candidates
}

fn static_page_explicit_points_from_value(value: &Value, field_path: Option<&str>) -> Vec<Value> {
    if let Some(array) = value.as_array() {
        return static_page_explicit_points_from_array(array, field_path);
    }
    for key in [
        "sampleData",
        "sample_data",
        "data",
        "values",
        "rows",
        "items",
    ] {
        if let Some(array) = value.get(key).and_then(Value::as_array) {
            let points = static_page_explicit_points_from_array(array, field_path);
            if !points.is_empty() {
                return points;
            }
        }
    }
    Vec::new()
}

fn static_page_explicit_points_from_array(array: &[Value], field_path: Option<&str>) -> Vec<Value> {
    array
        .iter()
        .enumerate()
        .filter_map(|(index, item)| static_page_explicit_point_from_item(item, index, field_path))
        .take(12)
        .collect()
}

fn static_page_explicit_point_from_item(
    item: &Value,
    index: usize,
    field_path: Option<&str>,
) -> Option<Value> {
    let value = static_page_explicit_point_value(item)?;
    let label = static_page_explicit_point_label(item, index);
    let mut point = Map::new();
    point.insert("label".to_string(), json!(label));
    point.insert("value".to_string(), json!(value));
    point.insert(
        "kind".to_string(),
        item.get("kind")
            .and_then(Value::as_str)
            .map(|kind| json!(kind))
            .unwrap_or_else(|| json!("module_data")),
    );
    point.insert("source".to_string(), json!("module_explicit_data"));
    if let Some(field_path) = field_path {
        point.insert("fieldPath".to_string(), json!(field_path));
    }
    Some(Value::Object(point))
}

fn static_page_explicit_point_value(item: &Value) -> Option<f64> {
    if let Some(value) = static_page_json_number(item) {
        return Some(value);
    }
    if let Some(array) = item.as_array() {
        return array.iter().find_map(static_page_json_number);
    }
    let object = item.as_object()?;
    for key in [
        "value",
        "amount",
        "count",
        "total",
        "score",
        "metric",
        "y",
        "订单金额",
        "金额",
        "收入",
        "数量",
    ] {
        if let Some(value) = object.get(key).and_then(static_page_json_number) {
            return Some(value);
        }
    }
    object.values().find_map(static_page_json_number)
}

fn static_page_explicit_point_label(item: &Value, index: usize) -> String {
    if let Some(array) = item.as_array() {
        if let Some(label) = array
            .iter()
            .find_map(|value| value.as_str().map(str::trim))
            .filter(|value| !value.is_empty())
        {
            return label.chars().take(18).collect();
        }
    }
    if let Some(object) = item.as_object() {
        for key in [
            "label", "name", "month", "date", "period", "category", "x", "月份", "日期", "分类",
        ] {
            if let Some(label) = object
                .get(key)
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
            {
                return label.chars().take(18).collect();
            }
        }
        for value in object.values() {
            if let Some(label) = value
                .as_str()
                .map(str::trim)
                .filter(|candidate| !candidate.is_empty())
            {
                return label.chars().take(18).collect();
            }
        }
    }
    format!("数据 {}", index + 1)
}

fn static_page_json_number(value: &Value) -> Option<f64> {
    if let Some(number) = value.as_f64() {
        return Some(number);
    }
    let text = value.as_str()?.trim();
    if text.is_empty() {
        return None;
    }
    let normalized = text
        .trim_end_matches('%')
        .replace(',', "")
        .replace('，', "");
    normalized.parse::<f64>().ok()
}

fn static_page_sample_data_quality(sample_data: &Value) -> &'static str {
    let Some(items) = sample_data.as_array() else {
        return "not_available";
    };
    if items.is_empty() {
        return "not_available";
    }
    if items
        .iter()
        .any(|item| item.get("kind").and_then(Value::as_str) == Some("evidence_value"))
    {
        return "evidence_value";
    }
    if items
        .iter()
        .any(|item| item.get("kind").and_then(Value::as_str) == Some("module_data"))
    {
        return "module_data";
    }
    "evidence_signal"
}

fn build_static_page_explicit_metric_points(
    evidence_items: &[Value],
    field_path: &str,
    keywords: &[&str],
) -> Vec<Value> {
    evidence_items
        .iter()
        .filter(|item| {
            item.get("type").and_then(Value::as_str).unwrap_or_default() == "retrieval_evidence"
        })
        .enumerate()
        .flat_map(|(evidence_index, item)| {
            static_page_evidence_value_lines(item)
                .into_iter()
                .enumerate()
                .filter_map(move |(line_index, line)| {
                    let line_lower = line.to_lowercase();
                    if !static_page_text_contains_any(&line_lower, keywords) {
                        return None;
                    }
                    let value = static_page_metric_value_from_line(&line)?;
                    Some(json!({
                        "label": static_page_metric_label_from_line(&line, item, evidence_index, line_index, keywords),
                        "value": value,
                        "kind": "evidence_value",
                        "fieldPath": field_path,
                        "evidenceIds": static_page_evidence_ids(item),
                        "evidenceRef": static_page_evidence_ref(item),
                    }))
                })
                .collect::<Vec<_>>()
        })
        .take(6)
        .collect()
}

fn static_page_evidence_value_lines(item: &Value) -> Vec<String> {
    let mut text = String::new();
    for key in ["content_excerpt", "summary"] {
        if let Some(value) = item.get(key).and_then(Value::as_str) {
            if !text.is_empty() {
                text.push('\n');
            }
            text.push_str(value);
        }
    }
    text.split(|character| matches!(character, '\n' | '\r' | ';' | '；'))
        .map(str::trim)
        .filter(|line| !line.is_empty())
        .map(ToOwned::to_owned)
        .collect()
}

fn static_page_metric_value_from_line(line: &str) -> Option<f64> {
    let candidates = static_page_number_candidates(line);
    if candidates.is_empty() {
        return None;
    }
    if candidates.len() == 1 {
        let value = candidates.first().copied()?;
        if static_page_number_looks_like_year(value)
            || (static_page_number_looks_like_period_part(value)
                && static_page_line_mentions_period(line))
        {
            return None;
        }
        return Some(value);
    }

    candidates
        .iter()
        .copied()
        .filter(|value| !static_page_number_looks_like_year(*value))
        .next_back()
        .or_else(|| candidates.last().copied())
}

fn static_page_number_candidates(line: &str) -> Vec<f64> {
    let mut values = Vec::new();
    let mut token = String::new();
    for character in line.chars().chain(std::iter::once(' ')) {
        let can_continue_number = character.is_ascii_digit()
            || character == '.'
            || character == ','
            || ((character == '-' || character == '+') && token.is_empty());
        if can_continue_number {
            token.push(character);
            continue;
        }
        if token.chars().any(|candidate| candidate.is_ascii_digit()) {
            let normalized = token.replace(',', "");
            if let Ok(value) = normalized.parse::<f64>() {
                values.push(value);
            }
        }
        token.clear();
    }
    values
}

fn static_page_number_looks_like_year(value: f64) -> bool {
    (1900.0..=2100.0).contains(&value) && value.fract().abs() < f64::EPSILON
}

fn static_page_number_looks_like_period_part(value: f64) -> bool {
    (1.0..=31.0).contains(&value) && value.fract().abs() < f64::EPSILON
}

fn static_page_line_mentions_period(line: &str) -> bool {
    let lower = line.to_lowercase();
    ["月", "日", "date", "month", "period", "季度", "周"]
        .iter()
        .any(|marker| lower.contains(marker))
}

fn static_page_metric_label_from_line(
    line: &str,
    item: &Value,
    evidence_index: usize,
    line_index: usize,
    keywords: &[&str],
) -> String {
    for part in line.split([',', '，', '|', '\t']) {
        let candidate = part.trim();
        if candidate.is_empty() {
            continue;
        }
        let candidate_lower = candidate.to_lowercase();
        if static_page_text_contains_any(&candidate_lower, keywords) {
            continue;
        }
        if static_page_string_is_numeric_only(candidate) {
            continue;
        }
        return candidate.chars().take(18).collect();
    }

    if line_index == 0 {
        static_page_evidence_point_label(item, evidence_index)
    } else {
        format!(
            "{}-{}",
            static_page_evidence_point_label(item, evidence_index),
            line_index + 1
        )
    }
}

fn static_page_string_is_numeric_only(value: &str) -> bool {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return false;
    }
    let numeric_chars = trimmed
        .chars()
        .filter(|character| {
            character.is_ascii_digit()
                || matches!(character, '.' | ',' | '-' | '+' | '%' | ' ' | '万' | '亿')
        })
        .count();
    numeric_chars == trimmed.chars().count()
}

fn static_page_field_keywords(field_path: &str) -> Vec<&'static str> {
    let normalized = field_path.to_ascii_lowercase();
    if normalized.contains("orders.amount") || normalized.contains("revenue") {
        return vec![
            "order", "orders", "amount", "revenue", "sales", "gmv", "订单", "金额", "收入",
        ];
    }
    if normalized.contains("orders.count") || normalized.contains("order_count") {
        return vec!["order", "orders", "count", "volume", "订单", "数量", "单量"];
    }
    if normalized.contains("customer") {
        return vec!["customer", "customers", "client", "客户", "用户"];
    }
    if normalized.contains("profit") || normalized.contains("margin") {
        return vec!["profit", "margin", "gross", "利润", "毛利"];
    }
    if normalized.contains("risk") {
        return vec!["risk", "delay", "warning", "风险", "延期", "预警"];
    }
    if normalized.contains("time") || normalized.contains("month") || normalized.contains("date") {
        return vec![
            "month", "date", "time", "period", "月份", "日期", "时间", "周期",
        ];
    }
    if normalized.contains("engagement") {
        return vec![
            "engagement",
            "newsletter",
            "open",
            "click",
            "触达",
            "互动",
            "打开",
            "点击",
        ];
    }
    Vec::new()
}

fn static_page_keyword_signal_score(item: &Value, keywords: &[&str]) -> f64 {
    let text = static_page_evidence_text(item).to_lowercase();
    let mut score = keywords
        .iter()
        .filter(|keyword| text.contains(&keyword.to_lowercase()))
        .count() as f64;

    if let Some(term_weights) = item
        .get("evidence_manifest")
        .and_then(|manifest| manifest.pointer("/embedding/term_weights"))
        .and_then(Value::as_object)
    {
        for (term, weight) in term_weights {
            if keywords
                .iter()
                .any(|keyword| keyword.eq_ignore_ascii_case(term))
            {
                score += weight.as_f64().unwrap_or(0.0).max(0.0);
            }
        }
    }

    if let Some(score_value) = item.get("score").and_then(Value::as_f64) {
        score += score_value.clamp(0.0, 1.0);
    } else if let Some(recall_score) = item.get("recall_score").and_then(Value::as_f64) {
        score += recall_score.clamp(0.0, 1.0);
    }

    (score * 10.0).round() / 10.0
}

fn static_page_evidence_point_label(item: &Value, index: usize) -> String {
    item.get("source_locator")
        .and_then(Value::as_str)
        .map(|value| {
            value
                .rsplit('/')
                .next()
                .unwrap_or(value)
                .split('#')
                .next()
                .unwrap_or(value)
                .trim()
                .to_string()
        })
        .filter(|value| !value.is_empty())
        .or_else(|| {
            item.get("summary")
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(|value| value.chars().take(18).collect::<String>())
        })
        .unwrap_or_else(|| format!("证据{}", index + 1))
}

fn push_static_page_field_candidate(
    candidates: &mut Vec<Value>,
    seen: &mut BTreeSet<String>,
    candidate: Value,
    limit: usize,
) {
    if candidates.len() >= limit {
        return;
    }
    let key = format!(
        "{}:{}",
        candidate
            .get("sourceId")
            .and_then(Value::as_str)
            .unwrap_or("unknown"),
        candidate
            .get("fieldPath")
            .and_then(Value::as_str)
            .unwrap_or_default(),
    );
    if key.ends_with(':') || !seen.insert(key) {
        return;
    }
    candidates.push(candidate);
}

fn static_page_evidence_ids(item: &Value) -> Vec<Value> {
    item.get("retrieval_evidence_id")
        .cloned()
        .map(|value| vec![value])
        .unwrap_or_default()
}

fn static_page_evidence_ref(item: &Value) -> Value {
    json!({
        "retrievalEvidenceId": item.get("retrieval_evidence_id").cloned().unwrap_or(Value::Null),
        "datasetId": item.get("dataset_id").cloned().unwrap_or(Value::Null),
        "documentId": item.get("document_id").cloned().unwrap_or(Value::Null),
        "documentChunkId": item.get("document_chunk_id").cloned().unwrap_or(Value::Null),
        "sourceLocator": item.get("source_locator").cloned().unwrap_or(Value::Null),
    })
}

fn static_page_evidence_text(item: &Value) -> String {
    let mut parts = Vec::new();
    for key in [
        "summary",
        "content_excerpt",
        "source_locator",
        "payload_filter_key",
    ] {
        if let Some(value) = item.get(key).and_then(Value::as_str) {
            parts.push(value.to_string());
        }
    }
    if let Some(term_weights) = item
        .get("evidence_manifest")
        .and_then(|manifest| manifest.pointer("/embedding/term_weights"))
        .and_then(Value::as_object)
    {
        parts.extend(term_weights.keys().cloned());
    }
    parts.join(" ")
}

fn static_page_text_contains_any(text: &str, keywords: &[&str]) -> bool {
    keywords
        .iter()
        .any(|keyword| text.contains(&keyword.to_lowercase()))
}

fn build_static_page_preview_contract(
    style_direction: &str,
    modules: &Value,
    render_spec: &Value,
    patch: Option<Value>,
) -> Value {
    let contract_source = json!({
        "style_direction": style_direction,
        "modules": modules,
        "render_spec": render_spec,
    });
    let mut contract = json!({
        "version": 1,
        "kind": "static-page-preview-contract",
        "status": "not_requested",
        "draftFingerprint": static_page_design_fingerprint(&contract_source),
        "imageJobId": Value::Null,
        "assetKey": Value::Null,
        "confirmedAt": Value::Null,
        "renderExpectation": "final HTML/CSS/SVG should reproduce the confirmed preview without baking editable text or charts into the image",
    });
    if let Some(patch) = patch {
        merge_json_value(&mut contract, &patch);
        set_payload_string(
            &mut contract,
            "draftFingerprint",
            &static_page_design_fingerprint(&contract_source),
        );
    }
    contract
}

fn static_page_design_fingerprint(value: &Value) -> String {
    let serialized = serde_json::to_string(value).unwrap_or_else(|_| "{}".to_string());
    let mut hash: u32 = 0;
    for byte in serialized.bytes() {
        hash = hash.wrapping_mul(31).wrapping_add(byte as u32);
    }
    format!("design-{hash:08x}")
}

fn static_page_payload_modules(payload: &Value) -> Value {
    payload
        .get("modules")
        .and_then(Value::as_array)
        .cloned()
        .map(Value::Array)
        .unwrap_or_else(|| Value::Array(Vec::new()))
}

fn static_page_payload_string(payload: &Value, keys: &[&str]) -> Option<String> {
    keys.iter().find_map(|key| {
        payload
            .get(*key)
            .and_then(Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(ToOwned::to_owned)
    })
}

fn static_page_payload_value(payload: &Value, keys: &[&str]) -> Option<Value> {
    keys.iter().find_map(|key| payload.get(*key).cloned())
}

async fn load_static_page_draft_or_404(
    state: &AppState,
    draft_id: StaticPageDraftId,
) -> std::result::Result<StaticPageDraft, ApiError> {
    state
        .storage
        .static_page_drafts()
        .get_by_id(state.tenant_id, draft_id)
        .await
        .map_err(ApiError::from_storage)?
        .ok_or_else(|| {
            ApiError::not_found(
                "static_page_draft_not_found",
                format!("static page draft {} was not found", draft_id),
            )
        })
}

async fn load_visible_static_page_draft(
    state: &AppState,
    draft_id: StaticPageDraftId,
    current_user_id: Option<UserId>,
) -> std::result::Result<StaticPageDraft, ApiError> {
    let draft = load_static_page_draft_or_404(state, draft_id).await?;
    if static_page_owner_is_visible(draft.owner_user_id, current_user_id) {
        return Ok(draft);
    }
    Err(static_page_draft_not_found_error(draft_id))
}

fn static_page_owner_is_visible(
    owner_user_id: Option<UserId>,
    current_user_id: Option<UserId>,
) -> bool {
    owner_user_id_is_visible(owner_user_id, current_user_id)
}

fn static_page_draft_not_found_error(draft_id: StaticPageDraftId) -> ApiError {
    ApiError::not_found(
        "static_page_draft_not_found",
        format!("static page draft {} was not found", draft_id),
    )
}

async fn load_static_page_image_job_or_404(
    state: &AppState,
    job_id: StaticPageImageJobId,
) -> std::result::Result<StaticPageImageJob, ApiError> {
    state
        .storage
        .static_page_image_jobs()
        .get_by_id(state.tenant_id, job_id)
        .await
        .map_err(ApiError::from_storage)?
        .ok_or_else(|| {
            ApiError::not_found(
                "static_page_image_job_not_found",
                format!("static page image job {} was not found", job_id),
            )
        })
}

async fn load_visible_static_page_image_job(
    state: &AppState,
    job_id: StaticPageImageJobId,
    current_user_id: Option<UserId>,
) -> std::result::Result<StaticPageImageJob, ApiError> {
    let job = load_static_page_image_job_or_404(state, job_id).await?;
    load_visible_static_page_draft(state, job.draft_id, current_user_id).await?;
    Ok(job)
}

async fn resolve_confirmed_static_page_image_job(
    state: &AppState,
    draft: &StaticPageDraft,
    requested_job_id: Option<StaticPageImageJobId>,
) -> std::result::Result<Option<StaticPageImageJob>, ApiError> {
    let job = if let Some(job_id) = requested_job_id {
        Some(load_static_page_image_job_or_404(state, job_id).await?)
    } else {
        state
            .storage
            .static_page_image_jobs()
            .list_by_draft(state.tenant_id, draft.id)
            .await
            .map_err(ApiError::from_storage)?
            .into_iter()
            .find(|job| matches!(job.status, StaticPageImageJobStatus::Confirmed))
    };
    let Some(job) = job else {
        return Err(ApiError::bad_request(
            "static_page_preview_not_confirmed",
            "confirm an effect preview before rendering the final static page".to_string(),
        ));
    };
    if job.draft_id != draft.id {
        return Err(ApiError::bad_request(
            "static_page_image_job_mismatch",
            "image job does not belong to this static page draft".to_string(),
        ));
    }
    if !matches!(job.status, StaticPageImageJobStatus::Confirmed) {
        return Err(ApiError::bad_request(
            "static_page_preview_not_confirmed",
            "confirm an effect preview before rendering the final static page".to_string(),
        ));
    }
    Ok(Some(job))
}

async fn append_static_page_draft_run_event(
    state: &AppState,
    draft: &StaticPageDraft,
    event_name: &str,
    payload: Value,
) -> std::result::Result<(), ApiError> {
    state
        .storage
        .assistant_runs()
        .append_event(
            state.tenant_id,
            draft.assistant_run_id,
            &NewAssistantRunEvent {
                event_name: event_name.to_string(),
                payload,
                created_at: Utc::now(),
            },
        )
        .await
        .map_err(ApiError::from_storage)?;
    Ok(())
}

async fn interpret_static_page_draft_intent_for_api(
    state: &AppState,
    draft: &StaticPageDraft,
    prompt: &str,
    draft_payload: &Value,
    messages: Vec<AssistantRunMessageView>,
) -> std::result::Result<StaticPageIntentOutcome, ApiError> {
    let run = state
        .storage
        .assistant_runs()
        .get_by_id(state.tenant_id, draft.assistant_run_id)
        .await
        .map_err(ApiError::from_storage)?
        .ok_or_else(|| {
            ApiError::not_found(
                "assistant_run_not_found",
                format!("assistant run {} was not found", draft.assistant_run_id),
            )
        })?;
    let runtime_request = StaticPageIntentRequest {
        prompt: prompt.to_string(),
        draft_payload: draft_payload.clone(),
        assistant_run_id: Some(draft.assistant_run_id.to_string()),
        startup_briefing: run.startup_briefing.clone(),
        selected_scope: draft.selected_scope.clone(),
        evidence_state: run.evidence_state.clone(),
        conversation_memory_refs: static_page_conversation_memory_refs(&run),
        messages: messages
            .into_iter()
            .map(|message| {
                json!({
                    "role": message.role.as_str(),
                    "content": message.content,
                })
            })
            .collect(),
    };
    let runtime_mode = std::env::var("STATIC_PAGE_INTENT_RUNTIME_MODE")
        .unwrap_or_else(|_| "deterministic".to_string());
    if runtime_mode != "provider" {
        return interpret_static_page_intent_deterministic(&runtime_request).map_err(|error| {
            ApiError::internal(
                "static_page_intent_runtime_failed",
                format!("static page deterministic intent failed: {error}"),
            )
        });
    }

    let runtime_provider = std::env::var("STATIC_PAGE_INTENT_RUNTIME_PROVIDER")
        .unwrap_or_else(|_| "static_page_intent_provider".to_string());
    let runtime_model = std::env::var("STATIC_PAGE_INTENT_RUNTIME_MODEL")
        .unwrap_or_else(|_| DEFAULT_STATIC_PAGE_INTENT_RUNTIME_MODEL.to_string());
    let provider_request = runtime_request.clone();
    let provider_result = tokio::task::spawn_blocking(move || {
        let provider = build_provider_from_env(
            "STATIC_PAGE_INTENT",
            "provider",
            runtime_provider,
            bootstrap_default_prompt_registry(),
        )?;
        interpret_static_page_intent_with_provider(
            &provider_request,
            provider.as_ref(),
            Some(&runtime_model),
        )
    })
    .await
    .map_err(|error| {
        ApiError::internal(
            "static_page_intent_join_failed",
            format!("static page intent worker join failed: {error}"),
        )
    })?;

    match provider_result {
        Ok(outcome) => Ok(outcome),
        Err(error) => {
            let mut fallback =
                interpret_static_page_intent_deterministic(&runtime_request).map_err(|fallback| {
                    ApiError::internal(
                        "static_page_intent_runtime_failed",
                        format!(
                            "static page provider failed ({error}); deterministic fallback also failed: {fallback}"
                        ),
                    )
                })?;
            fallback.runtime = json!({
                "source": "provider_fallback",
                "provider_failure": error.to_string(),
                "fallback": fallback.runtime,
            });
            Ok(fallback)
        }
    }
}

fn static_page_conversation_memory_refs(run: &AssistantRun) -> Vec<Value> {
    value_array(
        run.evidence_state
            .get("supplied_items")
            .cloned()
            .unwrap_or(Value::Null),
    )
    .into_iter()
    .filter(|item| item.get("type").and_then(Value::as_str) == Some("conversation_memory_item"))
    .collect()
}

fn validate_static_page_operations(
    operations: Vec<Value>,
) -> std::result::Result<Vec<Value>, ApiError> {
    sanitize_static_page_operations(operations)
        .map_err(|error| ApiError::bad_request("invalid_static_page_operation", error.to_string()))
}

fn summarize_static_page_operations(operations: &[Value]) -> String {
    if operations.is_empty() {
        return "未追加静态页操作。".to_string();
    }
    let mut types = BTreeMap::<String, usize>::new();
    for operation in operations {
        if let Some(operation_type) = static_page_operation_type(operation) {
            *types.entry(operation_type.to_string()).or_default() += 1;
        }
    }
    let labels = types
        .into_iter()
        .map(|(operation_type, count)| format!("{operation_type} x{count}"))
        .collect::<Vec<_>>()
        .join("，");
    format!("已追加静态页操作：{labels}。")
}

fn status_from_static_page_payload(payload: &Value) -> Option<StaticPageDraftStatus> {
    let status = payload
        .as_object()
        .and_then(|object| object.get("status"))
        .and_then(Value::as_str)
        .map(str::trim)?;
    match status {
        "draft" => Some(StaticPageDraftStatus::Draft),
        "planning" | "planned" => Some(StaticPageDraftStatus::Planned),
        "queued" => Some(StaticPageDraftStatus::Queued),
        "preview_ready" | "previewed" => Some(StaticPageDraftStatus::Previewed),
        "effect_confirmed" | "confirmed" => Some(StaticPageDraftStatus::Confirmed),
        "rendering" | "rendered" => Some(StaticPageDraftStatus::Rendered),
        "archived" => Some(StaticPageDraftStatus::Archived),
        _ => None,
    }
}

fn status_from_static_page_operations(operations: &[Value]) -> Option<StaticPageDraftStatus> {
    operations.iter().fold(None, |status, operation| {
        match static_page_operation_type(operation) {
            Some("queue_image_job") => Some(StaticPageDraftStatus::Queued),
            Some("mark_preview_ready") => Some(StaticPageDraftStatus::Previewed),
            Some("confirm_preview") => Some(StaticPageDraftStatus::Confirmed),
            Some("request_final_render") => Some(StaticPageDraftStatus::Rendered),
            Some(_) => Some(status.unwrap_or(StaticPageDraftStatus::Planned)),
            None => status,
        }
    })
}

fn static_page_operation_type(operation: &Value) -> Option<&str> {
    operation
        .as_object()
        .and_then(|object| object.get("type"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn apply_static_page_operations_to_payload(
    mut payload: Value,
    operations: &[Value],
    summary: Option<&str>,
) -> Value {
    ensure_json_object(&mut payload);
    for operation in operations {
        apply_static_page_operation_to_payload(&mut payload, operation);
    }
    if let Some(summary) = summary.filter(|value| !value.trim().is_empty()) {
        set_payload_string(&mut payload, "modelSummary", summary);
        set_payload_string(&mut payload, "model_summary", summary);
    }
    refresh_static_page_payload_design_contract(&mut payload);
    payload
}

fn apply_static_page_operation_to_payload(payload: &mut Value, operation: &Value) {
    let Some(operation_type) = static_page_operation_type(operation) else {
        return;
    };
    match operation_type {
        "change_style_direction" => {
            if let Some(style) = operation
                .get("styleDirection")
                .or_else(|| operation.get("style_direction"))
                .and_then(Value::as_str)
            {
                set_payload_string(payload, "styleDirection", style);
                set_payload_string(payload, "style_direction", style);
            }
        }
        "refresh_summary" => {
            if let Some(summary) = operation
                .get("modelSummary")
                .or_else(|| operation.get("model_summary"))
                .and_then(Value::as_str)
            {
                set_payload_string(payload, "modelSummary", summary);
                set_payload_string(payload, "model_summary", summary);
            }
        }
        "update_module" => {
            if let (Some(module_id), Some(patch)) = (
                static_page_operation_module_id(operation),
                operation.get("patch"),
            ) {
                merge_static_page_module(payload, module_id, patch);
            }
        }
        "change_visualization" => {
            if let (Some(module_id), Some(visualization_type)) = (
                static_page_operation_module_id(operation),
                operation.get("visualizationType").and_then(Value::as_str),
            ) {
                let mut visualization = json!({
                    "type": visualization_type,
                });
                if let Some(chart_runtime) = operation.get("chartRuntime") {
                    set_payload_value(&mut visualization, "chartRuntime", chart_runtime.clone());
                }
                if let Some(chart_options) = operation.get("chartOptions") {
                    set_payload_value(&mut visualization, "chartOptions", chart_options.clone());
                }
                merge_static_page_module(
                    payload,
                    module_id,
                    &json!({
                        "visualization": visualization,
                    }),
                );
            }
        }
        "change_data_binding" => {
            if let (Some(module_id), Some(data_binding)) = (
                static_page_operation_module_id(operation),
                operation.get("dataBinding"),
            ) {
                merge_static_page_module(
                    payload,
                    module_id,
                    &json!({
                        "dataBinding": data_binding,
                    }),
                );
            }
        }
        "add_module" => {
            if let Some(module) = operation.get("module") {
                push_static_page_module(payload, module.clone());
            }
        }
        "remove_module" => {
            if let Some(module_id) = static_page_operation_module_id(operation) {
                remove_static_page_module(payload, module_id);
            }
        }
        "move_module" | "resize_module" => {
            if let (Some(module_id), Some(layout)) = (
                static_page_operation_module_id(operation),
                operation.get("layout").or_else(|| operation.get("patch")),
            ) {
                merge_static_page_module(
                    payload,
                    module_id,
                    &json!({
                        "layout": layout,
                    }),
                );
            }
        }
        "reorder_modules" => {
            if let Some(order) = operation.get("order").and_then(Value::as_array) {
                set_payload_value(payload, "mobileOrder", Value::Array(order.clone()));
            }
        }
        "queue_image_job" => {
            set_payload_string(payload, "status", "queued");
            set_payload_value(
                payload,
                "imageJob",
                json!({
                    "id": operation.get("jobId").cloned().unwrap_or(Value::Null),
                    "status": "queued",
                    "queuePosition": operation.get("queuePosition").cloned().unwrap_or(Value::Null),
                    "queueMessage": operation
                        .get("queueMessage")
                        .and_then(Value::as_str)
                        .unwrap_or("资源正在排队，可以联系商务开通高级用户跳过等待。"),
                }),
            );
            set_payload_value(
                payload,
                "previewContract",
                json!({
                    "status": "queued",
                    "imageJobId": operation.get("jobId").cloned().unwrap_or(Value::Null),
                    "assetKey": Value::Null,
                    "queuePosition": operation.get("queuePosition").cloned().unwrap_or(Value::Null),
                    "confirmedAt": Value::Null,
                }),
            );
        }
        "mark_preview_ready" => {
            set_payload_string(payload, "status", "preview_ready");
            if let Some(preview) = operation.get("previewImage") {
                set_payload_value(payload, "previewImage", preview.clone());
                set_payload_value(
                    payload,
                    "previewContract",
                    json!({
                        "status": "preview_ready",
                        "imageJobId": preview.get("imageJobId").cloned().unwrap_or(Value::Null),
                        "assetKey": preview.get("assetKey").cloned().unwrap_or(Value::Null),
                        "queuePosition": Value::Null,
                    }),
                );
            }
        }
        "confirm_preview" => {
            set_payload_string(payload, "status", "effect_confirmed");
            if let Some(preview) = operation.get("previewImage") {
                set_payload_value(payload, "previewImage", preview.clone());
                set_payload_value(
                    payload,
                    "previewContract",
                    json!({
                        "status": "confirmed",
                        "imageJobId": preview.get("imageJobId").cloned().unwrap_or(Value::Null),
                        "assetKey": preview.get("assetKey").cloned().unwrap_or(Value::Null),
                        "queuePosition": Value::Null,
                        "confirmedAt": Utc::now(),
                    }),
                );
            }
        }
        "request_final_render" => {
            set_payload_string(payload, "status", "rendering");
            if let Some(final_page) = operation
                .get("finalPage")
                .or_else(|| operation.get("payload"))
            {
                set_payload_value(payload, "finalPage", final_page.clone());
            }
        }
        _ => {}
    }
}

fn refresh_static_page_payload_design_contract(payload: &mut Value) {
    ensure_json_object(payload);
    let style_direction =
        static_page_payload_string(payload, &["styleDirection", "style_direction"])
            .unwrap_or_else(|| "client-delivery".to_string());
    let modules = static_page_payload_modules(payload);
    let visual_spec = build_static_page_visual_spec(&style_direction);
    let render_spec = static_page_payload_value(payload, &["renderSpec", "render_spec"])
        .unwrap_or_else(build_static_page_render_spec);
    let selected_scope = payload
        .get("assistant_context")
        .and_then(|context| context.get("selected_scope"))
        .cloned()
        .or_else(|| payload.get("selected_scope").cloned())
        .unwrap_or(Value::Null);
    let data_snapshot = build_static_page_data_snapshot(payload, &selected_scope);
    let previous_contract =
        static_page_payload_value(payload, &["previewContract", "preview_contract"]);
    let preview_contract = build_static_page_preview_contract(
        &style_direction,
        &modules,
        &render_spec,
        previous_contract,
    );

    set_payload_string(payload, "styleDirection", &style_direction);
    set_payload_string(payload, "style_direction", &style_direction);
    set_payload_value(payload, "visualSpec", visual_spec.clone());
    set_payload_value(payload, "visual_spec", visual_spec);
    set_payload_value(payload, "renderSpec", render_spec.clone());
    set_payload_value(payload, "render_spec", render_spec);
    set_payload_value(payload, "dataSnapshot", data_snapshot.clone());
    set_payload_value(payload, "data_snapshot", data_snapshot);
    set_payload_value(payload, "previewContract", preview_contract.clone());
    set_payload_value(payload, "preview_contract", preview_contract);
}

fn append_static_page_operations_metadata(
    payload: &mut Value,
    operations: &[Value],
    prompt: Option<&str>,
    summary: &str,
) {
    ensure_json_object(payload);
    let Some(object) = payload.as_object_mut() else {
        return;
    };
    let entry = object
        .entry("operations".to_string())
        .or_insert_with(|| Value::Array(Vec::new()));
    if !entry.is_array() {
        *entry = Value::Array(Vec::new());
    }
    if let Some(items) = entry.as_array_mut() {
        let applied_at = Utc::now().to_rfc3339();
        for operation in operations {
            let mut operation = operation.clone();
            if let Some(object) = operation.as_object_mut() {
                object
                    .entry("appliedAt".to_string())
                    .or_insert_with(|| json!(applied_at));
                if let Some(prompt) = prompt.map(str::trim).filter(|value| !value.is_empty()) {
                    object
                        .entry("prompt".to_string())
                        .or_insert_with(|| json!(prompt));
                }
            }
            items.push(operation);
        }
    }
    object.insert("lastOperationSummary".to_string(), json!(summary));
}

fn static_page_operation_module_id(operation: &Value) -> Option<&str> {
    operation
        .get("targetModuleId")
        .or_else(|| operation.get("moduleId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

fn merge_static_page_module(payload: &mut Value, module_id: &str, patch: &Value) {
    let Some(modules) = payload
        .as_object_mut()
        .and_then(|object| object.get_mut("modules"))
        .and_then(Value::as_array_mut)
    else {
        return;
    };
    let Some(module) = modules.iter_mut().find(|module| {
        module
            .as_object()
            .and_then(|object| object.get("id"))
            .and_then(Value::as_str)
            == Some(module_id)
    }) else {
        return;
    };
    merge_json_value(module, patch);
}

fn push_static_page_module(payload: &mut Value, module: Value) {
    ensure_json_object(payload);
    let Some(object) = payload.as_object_mut() else {
        return;
    };
    let modules = object
        .entry("modules".to_string())
        .or_insert_with(|| Value::Array(Vec::new()));
    if !modules.is_array() {
        *modules = Value::Array(Vec::new());
    }
    if let Some(items) = modules.as_array_mut() {
        items.push(module);
    }
}

fn remove_static_page_module(payload: &mut Value, module_id: &str) {
    let Some(modules) = payload
        .as_object_mut()
        .and_then(|object| object.get_mut("modules"))
        .and_then(Value::as_array_mut)
    else {
        return;
    };
    modules.retain(|module| {
        module
            .as_object()
            .and_then(|object| object.get("id"))
            .and_then(Value::as_str)
            != Some(module_id)
    });
}

fn merge_json_value(target: &mut Value, patch: &Value) {
    match (target, patch) {
        (Value::Object(target_object), Value::Object(patch_object)) => {
            for (key, value) in patch_object {
                match target_object.get_mut(key) {
                    Some(existing) => merge_json_value(existing, value),
                    None => {
                        target_object.insert(key.clone(), value.clone());
                    }
                }
            }
        }
        (target, patch) => {
            *target = patch.clone();
        }
    }
}

fn ensure_json_object(value: &mut Value) {
    if !value.is_object() {
        *value = Value::Object(Map::new());
    }
}

fn set_payload_string(payload: &mut Value, key: &str, value: &str) {
    set_payload_value(payload, key, json!(value));
}

fn set_payload_value(payload: &mut Value, key: &str, value: Value) {
    ensure_json_object(payload);
    if let Some(object) = payload.as_object_mut() {
        object.insert(key.to_string(), value);
    }
}

#[derive(Debug)]
pub struct ApiError {
    status: StatusCode,
    payload: ApiErrorResponse,
}

impl ApiError {
    fn bad_request(code: &str, message: String) -> Self {
        Self {
            status: StatusCode::BAD_REQUEST,
            payload: ApiErrorResponse {
                code: code.to_string(),
                message,
            },
        }
    }

    fn not_found(code: &str, message: String) -> Self {
        Self {
            status: StatusCode::NOT_FOUND,
            payload: ApiErrorResponse {
                code: code.to_string(),
                message,
            },
        }
    }

    fn unauthorized(code: &str, message: String) -> Self {
        Self {
            status: StatusCode::UNAUTHORIZED,
            payload: ApiErrorResponse {
                code: code.to_string(),
                message,
            },
        }
    }

    fn too_many_requests(code: &str, message: String) -> Self {
        Self {
            status: StatusCode::TOO_MANY_REQUESTS,
            payload: ApiErrorResponse {
                code: code.to_string(),
                message,
            },
        }
    }

    fn internal(code: &str, message: String) -> Self {
        Self {
            status: StatusCode::INTERNAL_SERVER_ERROR,
            payload: ApiErrorResponse {
                code: code.to_string(),
                message,
            },
        }
    }

    fn from_storage(error: anyhow::Error) -> Self {
        if let Some(sqlx::Error::Database(db_error)) = error.downcast_ref::<sqlx::Error>() {
            match db_error.code().as_deref() {
                Some("23505") => {
                    return Self {
                        status: StatusCode::CONFLICT,
                        payload: ApiErrorResponse {
                            code: "conflict".to_string(),
                            message: db_error.message().to_string(),
                        },
                    };
                }
                Some("23503") => {
                    return Self::bad_request(
                        "foreign_key_violation",
                        db_error.message().to_string(),
                    );
                }
                _ => {}
            }
        }

        tracing::error!(error = ?error, "platform-api storage operation failed");
        Self::internal("storage_error", error.to_string())
    }

    fn from_transition(error: workflow_engine::WorkflowTransitionError) -> Self {
        match error {
            workflow_engine::WorkflowTransitionError::UnsupportedSignal => Self::bad_request(
                "unsupported_signal",
                "the requested workflow signal is not supported".to_string(),
            ),
            workflow_engine::WorkflowTransitionError::InvalidTransition(message) => {
                Self::bad_request("invalid_transition", message)
            }
        }
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        (self.status, Json(self.payload)).into_response()
    }
}

impl std::fmt::Display for ApiError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.payload.code, self.payload.message)
    }
}

impl std::error::Error for ApiError {}

